// Asset job contract: a pull-based queue with worker classes, plus a content-addressed object store.
// Interfaces first (research H-3d-games.md, decision 3): a Windows or GPU worker can plug in later without
// reworking the build service. HOST SEAM: no Nxeon imports; the host injects a real queue/store. The in-memory
// versions below exist for tests and for the first single-box lane. Pure Node (crypto only).
import { createHash } from "node:crypto";
import { WORKER_CLASSES, type WorkerClass } from "../adapters/asset-profile";

export const sha256Hex = (bytes: Uint8Array | string): string => createHash("sha256").update(bytes).digest("hex");
/** Content-addressed key: identical bytes always map to the same key, so uploads dedupe and keys never collide by name. */
export const contentKey = (bytes: Uint8Array | string): string => `sha256/${sha256Hex(bytes)}`;

export interface ObjectStore {
  /** Stores bytes and returns their content key (idempotent). */
  put(bytes: Uint8Array): Promise<string>;
  get(key: string): Promise<Uint8Array | null>;
  has(key: string): Promise<boolean>;
  delete(key: string): Promise<void>;
}

export function createMemoryObjectStore(): ObjectStore {
  const m = new Map<string, Uint8Array>();
  return {
    async put(bytes) { const k = contentKey(bytes); if (!m.has(k)) m.set(k, Uint8Array.from(bytes)); return k; },
    async get(key) { return m.get(key) ?? null; },
    async has(key) { return m.has(key); },
    async delete(key) { m.delete(key); },
  };
}

export type JobStatus = "queued" | "running" | "done" | "failed" | "expired";
export type AssetJob = {
  id: string;
  /** Free-form job kind the worker understands ("pack-ytd", "bc7-encode", "render-preview"). */
  type: string;
  workerClass: WorkerClass;
  /** Opaque tenant/project ids; the queue never reads Nxeon tables. */
  projectId: string;
  /** Content keys of the input objects. */
  inputs: readonly string[];
  /** Hard time budget; a job past it is expired, never left running. */
  timeoutMs: number;
  status: JobStatus;
  /** Content keys of the outputs once done. */
  outputs: readonly string[];
  error?: string;
  claimedBy?: string;
  claimedAt?: number;
};

export type EnqueueInput = Pick<AssetJob, "type" | "workerClass" | "projectId" | "inputs" | "timeoutMs">;

/** Pull-based: workers ask for work in the classes they serve; the queue never pushes into a worker (so a Windows guest needs no inbound port). */
export interface JobQueue {
  enqueue(job: EnqueueInput): Promise<AssetJob>;
  claim(worker: { id: string; classes: readonly WorkerClass[] }): Promise<AssetJob | null>;
  complete(id: string, workerId: string, outputs: readonly string[]): Promise<AssetJob | null>;
  fail(id: string, workerId: string, error: string): Promise<AssetJob | null>;
  /** Expire running jobs past their timeout; returns the expired jobs. */
  sweep(): Promise<AssetJob[]>;
  get(id: string): Promise<AssetJob | null>;
}

export const MAX_JOB_TIMEOUT_MS = 30 * 60 * 1000;

export function createMemoryJobQueue(now: () => number = Date.now): JobQueue {
  const jobs = new Map<string, AssetJob>();
  let seq = 0;
  return {
    async enqueue(j) {
      if (!WORKER_CLASSES.includes(j.workerClass)) throw new Error(`unknown worker class ${String(j.workerClass)}`);
      if (!(j.timeoutMs > 0 && j.timeoutMs <= MAX_JOB_TIMEOUT_MS)) throw new Error(`timeoutMs must be 1..${MAX_JOB_TIMEOUT_MS}`);
      const job: AssetJob = { id: `job_${++seq}`, ...j, status: "queued", outputs: [] };
      jobs.set(job.id, job);
      return { ...job };
    },
    async claim(w) {
      for (const j of jobs.values()) {
        if (j.status === "queued" && w.classes.includes(j.workerClass)) {
          j.status = "running"; j.claimedBy = w.id; j.claimedAt = now();
          return { ...j };
        }
      }
      return null;
    },
    async complete(id, workerId, outputs) {
      const j = jobs.get(id);
      if (!j || j.status !== "running" || j.claimedBy !== workerId) return null;
      j.status = "done"; j.outputs = [...outputs];
      return { ...j };
    },
    async fail(id, workerId, error) {
      const j = jobs.get(id);
      if (!j || j.status !== "running" || j.claimedBy !== workerId) return null;
      j.status = "failed"; j.error = error.slice(0, 500);
      return { ...j };
    },
    async sweep() {
      const out: AssetJob[] = [];
      for (const j of jobs.values()) {
        if (j.status === "running" && j.claimedAt !== undefined && now() - j.claimedAt > j.timeoutMs) { j.status = "expired"; j.error = "timeout"; out.push({ ...j }); }
      }
      return out;
    },
    async get(id) { const j = jobs.get(id); return j ? { ...j } : null; },
  };
}

// Canonical 3D asset record: glTF 2.0 geometry + a Cyrus sidecar manifest (research H-3d-games.md, section 3).
// The manifest carries what glTF cannot: provenance, the LEGAL CLASS, per-channel lossless layers and units.
// Channels are stored separately; packing into an engine's channels happens only at export (adapter's job).
// Pure, client-safe, Zod-validated; every failure is a structured issue, never a throw.
import { z } from "zod";
import { CHANNEL_ROLES, type ColorSpace } from "../adapters/asset-profile";
import { isSafeProjectPath } from "../engine-core/revisions";

export const ASSET_MANIFEST_SCHEMA_VERSION = 1 as const;

/** user-original / ai-generated-for-user / platform-library (Nxeon-owned or CC0 only) / third-party-licensed / game-derived. */
export const LEGAL_CLASSES = ["user-original", "ai-generated-for-user", "platform-library", "third-party-licensed", "game-derived"] as const;
export type LegalClass = (typeof LEGAL_CLASSES)[number];

export const SHA256_RE = /^[0-9a-f]{64}$/;
const sha = z.string().regex(SHA256_RE, "sha256 as 64 lowercase hex");
const safePath = z.string().refine((p) => isSafeProjectPath(p), "unsafe path");

const ChannelZ = z.object({
  role: z.enum(CHANNEL_ROLES),
  path: safePath,
  sha256: sha,
  width: z.number().int().min(1).max(16384),
  height: z.number().int().min(1).max(16384),
  colorSpace: z.enum(["srgb", "linear"]),
}).strict();

const ManifestZ = z.object({
  schemaVersion: z.literal(ASSET_MANIFEST_SCHEMA_VERSION),
  assetId: z.string().regex(/^[a-z][a-z0-9_]{0,47}$/),
  kind: z.enum(["model", "texture-set"]),
  game: z.string().regex(/^[a-z][a-z0-9-]{1,31}$/).optional(),
  units: z.literal("m"),
  upAxis: z.literal("+Y"),
  geometry: z.object({ path: safePath, sha256: sha, uvSets: z.number().int().min(0).max(8).default(1) }).strict().optional(),
  channels: z.array(ChannelZ).max(16).default([]),
  legalClass: z.enum(LEGAL_CLASSES),
  /** project = kept with the project; job = deleted when the job ends (the only legal option for game-derived content). */
  retention: z.enum(["project", "job"]).default("project"),
  provenance: z.object({
    source: z.enum(["user", "ai", "library", "import", "upload", "template"]),
    note: z.string().max(300).optional(),
    /** sha256 of the inputs this asset was derived from (a retexture lists the base it was painted on). */
    derivedFrom: z.array(sha).max(32).default([]),
  }).strict(),
}).strict();

export type AssetManifest = z.infer<typeof ManifestZ>;
export type ManifestIssue = { path: string; code: string; message: string };
export type ManifestParse = { ok: true; manifest: AssetManifest } | { ok: false; errors: ManifestIssue[] };

/** What the ledger allows for a class. The rule: game-derived content never outlives its job, never enters a library, never ships. */
export type LedgerRules = { storeBeyondJob: boolean; addToLibrary: boolean; redistribute: boolean; deliverable: "full" | "delta-only" };
export function ledgerRules(c: LegalClass): LedgerRules {
  switch (c) {
    case "game-derived": return { storeBeyondJob: false, addToLibrary: false, redistribute: false, deliverable: "delta-only" };
    case "third-party-licensed": return { storeBeyondJob: true, addToLibrary: false, redistribute: false, deliverable: "full" };
    // Owner decision 2026-10-10: assets made in Cyrus contribute to the community library automatically (no opt-in).
    default: return { storeBeyondJob: true, addToLibrary: true, redistribute: true, deliverable: "full" };
  }
}

/**
 * Whether a manifest is eligible for automatic contribution to the community library. Eligible = made inside Cyrus
 * (user-original authored in a studio, ai-generated-for-user) or already Nxeon's own, and not derived from any other bytes.
 * Never: game-derived, third-party-licensed, imported/uploaded/template content, or anything with a derivedFrom entry. Eligible is not published: the
 * content filters (trademark, real-weapon, adult content) and the terms-of-service grant still gate publication.
 */
export function libraryEligible(m: Pick<AssetManifest, "legalClass" | "provenance">): boolean {
  if (!ledgerRules(m.legalClass).addToLibrary) return false;
  // Only content authored inside Cyrus from nothing outside it: no imports/uploads/templates, and nothing derived from other bytes
  // (a livery painted on someone's template lists that template in derivedFrom, so it is never auto-contributed).
  if (!["user", "ai", "library"].includes(m.provenance.source)) return false;
  return m.provenance.derivedFrom.length === 0;
}

export function validateAssetManifest(raw: unknown): ManifestParse {
  const r = ManifestZ.safeParse(raw);
  if (!r.success) return { ok: false, errors: r.error.issues.map((i) => ({ path: i.path.join(".") || "manifest", code: "invalid", message: i.message })) };
  const m = r.data;
  const errors: ManifestIssue[] = [];
  const add = (path: string, code: string, message: string) => errors.push({ path, code, message });
  const seen = new Set<string>();
  m.channels.forEach((c, i) => {
    if (seen.has(c.role)) add(`channels.${i}.role`, "duplicate_role", `channel role ${c.role} appears twice`);
    seen.add(c.role);
    const want: ColorSpace | null = c.role === "albedo" || c.role === "emissive" ? "srgb" : c.role === "normal" || c.role === "roughness" || c.role === "metallic" || c.role === "ao" || c.role === "height" ? "linear" : null;
    if (want && c.colorSpace !== want) add(`channels.${i}.colorSpace`, "wrong_color_space", `${c.role} must be ${want}`);
  });
  if (m.kind === "model" && !m.geometry) add("geometry", "geometry_required", "a model needs a geometry file");
  if (m.kind === "texture-set" && m.channels.length === 0) add("channels", "channels_required", "a texture set needs at least one channel");
  if (m.legalClass === "game-derived") {
    if (m.retention !== "job") add("retention", "game_derived_must_be_job", "game-derived assets are kept only for the job and must use retention \"job\"");
    if (!m.game) add("game", "game_required", "a game-derived asset must name its game");
    if (m.provenance.derivedFrom.length === 0) add("provenance.derivedFrom", "derived_from_required", "list the base content hashes so a delta can be computed");
  }
  if (m.legalClass === "platform-library" && m.provenance.source !== "library") add("provenance.source", "library_source", "platform-library assets come from the library");
  return errors.length ? { ok: false, errors } : { ok: true, manifest: m };
}
// Asset profile: what ONE game's adapter declares about 3D/texture assets (MULTIGAME research H-3d-games.md, section 3).
// Interfaces + a validator only. Nothing here changes behaviour; Minecraft is the first filled-in profile, every
// other game declares its own when its adapter is written. Pure, client-safe, no Nxeon imports.
import type { AdapterMaturity } from "./types";

/** How custom assets reach players. Only the first and the two workshop forms need no player action. */
export const DELIVERY_STRATEGIES = ["server-streamed", "workshop-user-publishes", "workshop-platform-publishes", "client-manual", "none"] as const;
export type DeliveryStrategy = (typeof DELIVERY_STRATEGIES)[number];

/** Which kind of worker a job needs. linux-cpu = node-2 style builds; windows-tools = Windows-only game tools; gpu = image/3D models. */
export const WORKER_CLASSES = ["linux-cpu", "windows-tools", "gpu"] as const;
export type WorkerClass = (typeof WORKER_CLASSES)[number];

/** none = nothing from the game needed; user-supplied = the user brings templates/base files; platform-licensed = Nxeon holds a licence. */
export const REQUIRED_GAME_FILES = ["none", "user-supplied", "platform-licensed"] as const;
export type RequiredGameFiles = (typeof REQUIRED_GAME_FILES)[number];

/** Channel roles of a texture set. Stored as separate lossless layers; packed into engine channels only at export. */
export const CHANNEL_ROLES = ["albedo", "normal", "roughness", "metallic", "ao", "emissive", "height", "opacity", "mask"] as const;
export type ChannelRole = (typeof CHANNEL_ROLES)[number];

export type ColorSpace = "srgb" | "linear";
export type NormalConvention = "opengl" | "directx" | "none";
export type TextureCompression = "png" | "bc1" | "bc3" | "bc5" | "bc7" | "ktx2";
export type EngineFamily = "minecraft-java" | "unreal" | "unity" | "source" | "rage" | "creation" | "hytale" | "other";

/** Where a role lands in the game's packed texture: a file name pattern and the channel(s) of it. */
export type ChannelTarget = { file: string; channels: "rgb" | "rgba" | "r" | "g" | "b" | "a" };

/** What the game owner's published terms say about hosted modding. `reviewed` is false until a human read the page. */
export type LegalPolicy = {
  policyUrl: string | null;
  /** true / false only when a reviewer read the source; otherwise "unknown" (the honest default). */
  commercialOk: boolean | "unknown";
  aiOk: boolean | "unknown";
  /** A game's own assets are never redistributed, so this is the literal false. */
  redistributeBase: false;
  monetisationRule?: string;
  attestationRequired: boolean;
  /** ISO date the policy page was last read, or null. */
  retrievedAt: string | null;
  reviewed: boolean;
};

export type AssetProfile = {
  game: string;
  engineFamily: EngineFamily;
  meshFormats: readonly string[];
  textureFormats: readonly string[];
  compression: readonly TextureCompression[];
  channelMap: Readonly<Partial<Record<ChannelRole, ChannelTarget>>>;
  normalConvention: NormalConvention;
  colorSpace: Readonly<Partial<Record<ChannelRole, ColorSpace>>>;
  /** Largest texture edge in pixels the game/adapter accepts. */
  maxTextureRes: number;
  /** reuse-template = the user's UV layout is kept; new = Cyrus may unwrap; none = the game has no UVs to manage. */
  uvRules: "reuse-template" | "new" | "none";
  skeletonPolicy: "reuse" | "own" | "none" | "forbidden";
  packaging: string;
  delivery: DeliveryStrategy;
  workerClass: WorkerClass;
  requiredGameFiles: RequiredGameFiles;
  legal: LegalPolicy;
  validators: readonly string[];
  previewShader: string;
  maturity: AdapterMaturity;
};

export type ProfileIssue = { path: string; code: string; message: string };

/** Cheap structural rules a profile must satisfy; returns issues, never throws. */
export function validateAssetProfile(p: AssetProfile): ProfileIssue[] {
  const out: ProfileIssue[] = [];
  const add = (path: string, code: string, message: string) => out.push({ path, code, message });
  if (!DELIVERY_STRATEGIES.includes(p.delivery)) add("delivery", "bad_delivery", `unknown delivery strategy ${String(p.delivery)}`);
  if (!WORKER_CLASSES.includes(p.workerClass)) add("workerClass", "bad_worker_class", `unknown worker class ${String(p.workerClass)}`);
  if (!REQUIRED_GAME_FILES.includes(p.requiredGameFiles)) add("requiredGameFiles", "bad_required_files", `unknown value ${String(p.requiredGameFiles)}`);
  if ((p.legal.redistributeBase as unknown) !== false) add("legal.redistributeBase", "must_be_false", "a game's base assets are never redistributed");
  if ((p.legal.commercialOk === true || p.legal.aiOk === true) && !p.legal.reviewed) add("legal.reviewed", "unreviewed_claim", "commercialOk/aiOk can only be true after a human reviewed the policy");
  if (p.legal.reviewed && (!p.legal.policyUrl || !p.legal.retrievedAt)) add("legal.policyUrl", "missing_source", "a reviewed policy needs its url and retrieval date");
  if (p.maturity === "stable" && !p.legal.reviewed) add("maturity", "stable_needs_legal", "a stable adapter needs a reviewed legal policy");
  if (p.delivery === "client-manual" && p.maturity === "stable") add("delivery", "manual_not_stable", "assets players must install by hand cannot be a stable path");
  if (p.requiredGameFiles !== "none" && p.legal.attestationRequired !== true) add("legal.attestationRequired", "attestation_needed", "user-supplied or licensed game files need an ownership attestation");
  if (p.workerClass === "windows-tools" && p.requiredGameFiles === "platform-licensed") add("requiredGameFiles", "windows_licensed", "a Windows worker must not hold a platform-licensed game install without a separate legal review");
  if (!(p.maxTextureRes >= 16 && p.maxTextureRes <= 16384)) add("maxTextureRes", "bad_res", "maxTextureRes must be between 16 and 16384");
  if (p.channelMap.albedo && p.colorSpace.albedo && p.colorSpace.albedo !== "srgb") add("colorSpace.albedo", "albedo_srgb", "albedo is stored in sRGB");
  if (p.colorSpace.normal && p.colorSpace.normal !== "linear") add("colorSpace.normal", "normal_linear", "normal maps are linear data");
  if (p.channelMap.normal && p.normalConvention === "none") add("normalConvention", "normal_needs_convention", "a normal channel needs opengl or directx");
  for (const role of Object.keys(p.channelMap)) if (!CHANNEL_ROLES.includes(role as ChannelRole)) add(`channelMap.${role}`, "bad_role", `unknown channel role ${role}`);
  return out;
}
// Host registry: Cyrus code asks for the host here, never for the platform. SERVER ONLY (the default loads the
// Nxeon implementation). Tests and a standalone deployment call setHost() once at startup with their own host.
import type { CyrusHost } from "./types";
import { nxeonHost } from "./nxeon";

export type { CyrusHost, HostRateLimit } from "./types";
export { isTrue } from "./types";

let current: CyrusHost = nxeonHost;

/** The active host (the Nxeon implementation unless setHost replaced it). */
export const getHost = (): CyrusHost => current;
/** Replace the host (tests, standalone Cyrus). Returns a function that restores the previous host. */
export function setHost(h: CyrusHost): () => void {
  const prev = current;
  current = h;
  return () => { current = prev; };
}
// The Nxeon implementation of the Cyrus host seam. SERVER ONLY. This is the single file under lib/cyrus/host that
// reaches Nxeon: every method delegates to the existing platform function unchanged, so behaviour inside Nxeon is
// identical to calling them directly. Moving Cyrus out means replacing this file, nothing else.
import { getSetting, getSettingBool, getSettingInt, getAllSettings, setSetting } from "../../settings";
import { checkRateLimit } from "../../rate-limit";
import { recordAudit } from "../../audit";
import type { CyrusHost } from "./types";

export const nxeonHost: CyrusHost = {
  settings: {
    get: (key, fallback) => getSetting(key, fallback),
    getBool: (key, fallback) => getSettingBool(key, fallback),
    getInt: (key, fallback) => getSettingInt(key, fallback),
    getAll: () => getAllSettings(),
    set: (key, value) => setSetting(key, value),
  },
  rateLimit: { check: (key, opts) => checkRateLimit(key, opts) },
  audit: { record: (userId, action, detail) => recordAudit(userId, action, detail) },
};
// The Cyrus HOST SEAM: everything Cyrus needs from the platform it runs inside, as small interfaces.
// Inside Nxeon the implementation is lib/cyrus/host/nxeon.ts (the ONLY file under lib/cyrus allowed to import Nxeon
// internals, enforced by test/cyrus-host-seam.test.ts). Standalone Cyrus supplies its own implementation of this
// interface (or an adapter that calls the Nxeon API). Add a method here when Cyrus needs a new platform service,
// never import the platform directly. Pure types: client-safe, no imports.

export type HostRateLimit = { ok: boolean; retryAfterSec: number; remaining: number };

export interface CyrusHost {
  /** Key/value settings and feature flags (Nxeon: the Setting table). Values are strings; missing keys use the fallback. */
  settings: {
    get(key: string, fallback?: string): Promise<string>;
    getBool(key: string, fallback?: boolean): Promise<boolean>;
    getInt(key: string, fallback?: number): Promise<number>;
    getAll(): Promise<Record<string, string>>;
    set(key: string, value: string): Promise<void>;
  };
  /** Fixed-window rate limiter keyed by an opaque string. Synchronous, in-process. */
  rateLimit: {
    check(key: string, opts: { max: number; windowMs: number }): HostRateLimit;
  };
  /** Append-only audit trail; attribution to the acting admin is the host's job. */
  audit: {
    record(userId: string | null, action: string, detail?: string): Promise<void>;
  };
}

/** Settings stored as "true"/"on"/"1" are true. Same rule as the platform's own coercion. */
export function isTrue(v: string | undefined | null): boolean {
  return v === "true" || v === "on" || v === "1";
}

