# mg_geo.py -- Cyrus meshgen geometry kit (from the 2026-10-10 parts-kit PoC, pk_geo.py, generalised).
# Closed bmesh primitives accumulated into named Parts; every primitive is its own closed shell (manifold per shell,
# NOT boolean-unioned). Each face carries a material slot index. A template declares its own slot list + palette.
# Runs inside Blender only (bpy, bmesh). Deterministic: no randomness, no time, no file or network access.
import bpy, bmesh, math
from mathutils import Matrix, Vector, Euler

HEX_RE_CHARS = set('0123456789abcdefABCDEF')


def hex2lin(h):
    h = str(h).lstrip('#')
    if len(h) != 6 or any(c not in HEX_RE_CHARS for c in h):
        raise ValueError(f'colour {h!r} is not #rrggbb')
    return tuple((int(h[i:i + 2], 16) / 255.0) ** 2.2 for i in (0, 2, 4))


def make_materials(slots, defaults, pal):
    """slots: ordered slot names; defaults: slot -> (hex, metallic, roughness, emission); pal: spec palette overrides."""
    pal = pal or {}
    for k in pal:
        if k not in slots:
            raise ValueError(f'palette slot {k!r} not in {list(slots)}')
    mats = []
    for s in slots:
        hx, me, ro, em = defaults[s]
        v = pal.get(s)
        if isinstance(v, str):
            hx = v
        elif isinstance(v, dict):
            hx = v.get('color', hx); me = v.get('metal', me); ro = v.get('rough', ro); em = v.get('emit', em)
        m = bpy.data.materials.new('mat_' + s); m.use_nodes = True
        b = m.node_tree.nodes['Principled BSDF']; c = hex2lin(hx)
        b.inputs['Base Color'].default_value = (*c, 1)
        b.inputs['Metallic'].default_value = float(me); b.inputs['Roughness'].default_value = float(ro)
        if em:
            b.inputs['Emission Color'].default_value = (*c, 1); b.inputs['Emission Strength'].default_value = float(em)
        mats.append(m)
    return mats


def _bevel(bm, w, ang=35):
    if w <= 0:
        return
    es = [e for e in bm.edges if len(e.link_faces) == 2 and e.calc_face_angle(0) > math.radians(ang)]
    if es:
        bmesh.ops.bevel(bm, geom=es, offset=w, segments=1, profile=0.5, affect='EDGES', clamp_overlap=True)


def _M(loc, rot):
    return Matrix.Translation(Vector(loc)) @ Euler(rot, 'XYZ').to_matrix().to_4x4()


AXIS_BASE = {'x': Matrix.Rotation(math.pi / 2, 4, 'Y'), 'y': Matrix.Rotation(-math.pi / 2, 4, 'X'), 'z': Matrix.Identity(4)}


class Part:
    """One output object. Primitives are appended as separate closed shells."""

    def __init__(self, name, slots):
        self.name = name; self.bm = bmesh.new(); self.slots = list(slots)
        self.sidx = {s: i for i, s in enumerate(self.slots)}; self.prims = 0

    def _slot(self, slot):
        if slot not in self.sidx:
            raise ValueError(f'material slot {slot!r} not in {self.slots}')
        return self.sidx[slot]

    def _add(self, src, slot, M=None, slots_per_face=None):
        idx = self._slot(slot)
        bmesh.ops.recalc_face_normals(src, faces=src.faces)
        if M is not None:
            bmesh.ops.transform(src, matrix=M, verts=src.verts)
        vm = {v: self.bm.verts.new(v.co) for v in src.verts}
        for i, f in enumerate(src.faces):
            nf = self.bm.faces.new([vm[v] for v in f.verts])
            nf.material_index = self._slot(slots_per_face[i]) if slots_per_face else idx
        src.free(); self.prims += 1

    def box(self, c, dim, slot, bevel=0.0, rot=(0, 0, 0)):
        bm = bmesh.new(); bmesh.ops.create_cube(bm, size=1.0)
        bmesh.ops.scale(bm, vec=Vector(dim), verts=bm.verts)
        _bevel(bm, min(bevel, min(dim) * 0.3)); self._add(bm, slot, _M(c, rot))

    def cyl(self, c, r, length, slot, axis='x', r2=None, seg=16, bevel=0.0, rot=(0, 0, 0)):
        bm = bmesh.new()
        bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=int(seg), radius1=r, radius2=r if r2 is None else r2, depth=length, calc_uvs=False)
        _bevel(bm, min(bevel, r * 0.5, length * 0.3))
        self._add(bm, slot, _M(c, rot) @ AXIS_BASE[axis])

    def sphere(self, c, r, slot, seg=12, rings=8, scale=(1, 1, 1)):
        bm = bmesh.new()
        bmesh.ops.create_uvsphere(bm, u_segments=int(seg), v_segments=int(rings), radius=r, calc_uvs=False)
        bmesh.ops.scale(bm, vec=Vector(scale), verts=bm.verts)
        self._add(bm, slot, Matrix.Translation(Vector(c)))

    def tube(self, c, r_out, r_in, length, slot, axis='x', seg=16, rot=(0, 0, 0)):
        """Hollow cylinder as ONE closed shell (outer wall, inner wall, two annular caps)."""
        if not (0 < r_in < r_out):
            raise ValueError('tube needs 0 < inner radius < outer radius')
        bm = bmesh.new(); n = int(seg); h = length / 2
        ring = lambda r, z: [bm.verts.new((r * math.cos(2 * math.pi * i / n), r * math.sin(2 * math.pi * i / n), z)) for i in range(n)]
        ob, ot, ib, it = ring(r_out, -h), ring(r_out, h), ring(r_in, -h), ring(r_in, h)
        for i in range(n):
            j = (i + 1) % n
            bm.faces.new((ob[i], ob[j], ot[j], ot[i])); bm.faces.new((ib[j], ib[i], it[i], it[j]))
            bm.faces.new((ot[i], ot[j], it[j], it[i])); bm.faces.new((ob[j], ob[i], ib[i], ib[j]))
        self._add(bm, slot, _M(c, rot) @ AXIS_BASE[axis])

    def rod(self, p0, p1, r, slot, seg=8):
        p0 = Vector(p0); p1 = Vector(p1); d = p1 - p0
        if d.length < 1e-6:
            raise ValueError('rod endpoints coincide')
        bm = bmesh.new()
        bmesh.ops.create_cone(bm, cap_ends=True, cap_tris=False, segments=int(seg), radius1=r, radius2=r, depth=d.length, calc_uvs=False)
        q = Vector((0, 0, 1)).rotation_difference(d.normalized())
        self._add(bm, slot, Matrix.Translation((p0 + p1) / 2) @ q.to_matrix().to_4x4())

    def prism(self, pts, w, slot, bevel=0.0, plane='xz', c=0.0, M=None):
        """plane 'xz': pts=(x,z) extruded across y by w centred on y=c. 'yz': pts=(y,z) extruded along x from c to c+w.
        'xy': pts=(x,y) extruded along z by w centred on z=c."""
        if len(pts) < 3:
            raise ValueError('prism needs at least 3 points')
        bm = bmesh.new(); n = len(pts)
        if plane == 'xz':
            a = [bm.verts.new((x, c - w / 2, z)) for x, z in pts]; b = [bm.verts.new((x, c + w / 2, z)) for x, z in pts]
        elif plane == 'yz':
            a = [bm.verts.new((c, y, z)) for y, z in pts]; b = [bm.verts.new((c + w, y, z)) for y, z in pts]
        else:
            a = [bm.verts.new((x, y, c - w / 2)) for x, y in pts]; b = [bm.verts.new((x, y, c + w / 2)) for x, y in pts]
        bm.faces.new(a); bm.faces.new(b[::-1])
        for i in range(n):
            j = (i + 1) % n; bm.faces.new((a[i], a[j], b[j], b[i]))
        _bevel(bm, min(bevel, w * 0.3)); self._add(bm, slot, M)

    def loft(self, sections, slot, face_slots=None, cap_start=True, tip=None):
        """sections: list of equal-length vertex loops (lists of (x,y,z)); consecutive loops are bridged with quads.
        face_slots(i_section, i_edge) -> slot name for the side quad (lets one shell carry several materials).
        tip: optional (x,y,z) apex closing the last loop with triangles; otherwise the last loop gets an n-gon cap."""
        bm = bmesh.new(); loops = [[bm.verts.new(p) for p in s] for s in sections]; n = len(loops[0]); fs = []
        for k in range(len(loops) - 1):
            A, B = loops[k], loops[k + 1]
            for i in range(n):
                j = (i + 1) % n; bm.faces.new((A[i], A[j], B[j], B[i])); fs.append(face_slots(k, i) if face_slots else slot)
        if cap_start:
            bm.faces.new(loops[0][::-1]); fs.append(slot)
        if tip is not None:
            t = bm.verts.new(tip); L = loops[-1]
            for i in range(n):
                j = (i + 1) % n; bm.faces.new((L[i], L[j], t)); fs.append(face_slots(len(loops) - 1, i) if face_slots else slot)
        else:
            bm.faces.new(loops[-1]); fs.append(slot)
        # face order in bm.faces matches creation order
        self._add(bm, slot, None, slots_per_face=fs)

    def to_object(self, mats, sharp_deg=35):
        bm = self.bm
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
        for f in bm.faces:
            f.smooth = True
        for e in bm.edges:
            if len(e.link_faces) != 2 or e.calc_face_angle(0) > math.radians(sharp_deg):
                e.smooth = False
        me = bpy.data.meshes.new(self.name); bm.to_mesh(me); bm.free()
        for m in mats:
            me.materials.append(m)
        ob = bpy.data.objects.new(self.name, me); bpy.context.collection.objects.link(ob)
        return ob


def finish(parts, mats):
    """Parts (dict or list) -> list of bpy objects, skipping empty parts."""
    objs = []
    for p in (parts.values() if isinstance(parts, dict) else parts):
        if len(p.bm.faces):
            objs.append(p.to_object(mats))
        else:
            p.bm.free()
    return objs

