        """plane 'xz': pts=(x,z) extruded across y by w centred on y=c. 'yz': pts=(y,z) extruded along x from c to c+w.
        'xy': pts=(x,y) extruded along z by w centred on z=c."""
        if len(pts) < 3:
            raise ValueError('prism needs at least 3 points')
        bm = bmesh.new(); n = len(pts)
        if plane == 'xz':
            a = [bm.verts.new((x, c - w / 2, z)) for x, z in pts]; b = [bm.verts.new((x, c + w / 2, z)) for x, z in pts]
        elif plane == 'yz':
            a = [bm.verts.new((c, y, z)) for y, z in pts]; b = [bm.verts.new((c + w, y, z)) for y, z in pts]
        else:
            a = [bm.verts.new((x, y, c - w / 2)) for x, y in pts]; b = [bm.verts.new((x, y, c + w / 2)) for x, y in pts]
        bm.faces.new(a); bm.faces.new(b[::-1])
        for i in range(n):
            j = (i + 1) % n; bm.faces.new((a[i], a[j], b[j], b[i]))
        _bevel(bm, min(bevel, w * 0.3)); self._add(bm, slot, M)

    def loft(self, sections, slot, face_slots=None, cap_start=True, tip=None):
        """sections: list of equal-length vertex loops (lists of (x,y,z)); consecutive loops are bridged with quads.
        face_slots(i_section, i_edge) -> slot name for the side quad (lets one shell carry several materials).
        tip: optional (x,y,z) apex closing the last loop with triangles; otherwise the last loop gets an n-gon cap."""
        bm = bmesh.new(); loops = [[bm.verts.new(p) for p in s] for s in sections]; n = len(loops[0]); fs = []
        for k in range(len(loops) - 1):
            A, B = loops[k], loops[k + 1]
            for i in range(n):
                j = (i + 1) % n; bm.faces.new((A[i], A[j], B[j], B[i])); fs.append(face_slots(k, i) if face_slots else slot)
        if cap_start:
            bm.faces.new(loops[0][::-1]); fs.append(slot)
        if tip is not None:
            t = bm.verts.new(tip); L = loops[-1]
            for i in range(n):
                j = (i + 1) % n; bm.faces.new((L[i], L[j], t)); fs.append(face_slots(len(loops) - 1, i) if face_slots else slot)
        else:
            bm.faces.new(loops[-1]); fs.append(slot)
        # face order in bm.faces matches creation order
        self._add(bm, slot, None, slots_per_face=fs)

    def to_object(self, mats, sharp_deg=35):
        bm = self.bm
        bmesh.ops.recalc_face_normals(bm, faces=bm.faces)
        for f in bm.faces:
            f.smooth = True
        for e in bm.edges:
            if len(e.link_faces) != 2 or e.calc_face_angle(0) > math.radians(sharp_deg):
                e.smooth = False
        me = bpy.data.meshes.new(self.name); bm.to_mesh(me); bm.free()
        for m in mats:
            me.materials.append(m)
        ob = bpy.data.objects.new(self.name, me); bpy.context.collection.objects.link(ob)
        return ob


def finish(parts, mats):
    """Parts (dict or list) -> list of bpy objects, skipping empty parts."""
    objs = []
    for p in (parts.values() if isinstance(parts, dict) else parts):
        if len(p.bm.faces):
            objs.append(p.to_object(mats))
        else:
            p.bm.free()
    return objs

