#   TEMPLATE_ID, VERSION, SLOTS, DEFAULT_PAL, VIEWS, SELFTEST (list of specs covering every enum), build(spec) -> [bpy objects]
# Frame: +X muzzle, Z up, bore axis z=0, metres. The model only ever writes `spec` (JSON); this file is fixed code.
from mg_geo import Part, make_materials, finish
from tpl_rifle_parts import RECV, GRIP, MAG, STOCK, HAND, barrel, sights, trigger_guard, g

TEMPLATE_ID = 'rifle'
VERSION = 1
SLOTS = ['body', 'furniture', 'barrel', 'mag', 'accent', 'glow', 'dark']
DEFAULT_PAL = {  # slot: (hex, metallic, roughness, emission strength)
    'body': ('#3a3d42', 0.8, 0.40, 0), 'furniture': ('#6b3a1c', 0.0, 0.5, 0), 'barrel': ('#1c1e21', 0.9, 0.35, 0),
    'mag': ('#16181b', 0.6, 0.45, 0), 'accent': ('#8a8f98', 0.5, 0.4, 0), 'glow': ('#00e5ff', 0.0, 0.3, 6.0),
    'dark': ('#0b0c0e', 0.2, 0.7, 0)}
VIEWS = [(0, 5, 0.78), (35, 25, 0.85), (0, 82, 0.8)]  # side, 3/4, top  (azimuth deg, elevation deg, distance factor)
PART_NAMES = ['receiver', 'grip', 'magazine', 'stock', 'handguard', 'barrel', 'sights', 'trim']
ACCENTS = ['receiver_side', 'receiver_top', 'handguard_side', 'magazine_window', 'stock_side', 'barrel_ring']


def pick(table, S, key, default):
    st = (S or {}).get('style', default)
    if st not in table:
        raise ValueError(f'{key}.style={st!r} not in {sorted(table)}')
    return table[st]


def accents(P, A, lst, glow='glow'):
    T = P['trim']; w = A['w']
    for a in lst or []:
        if a == 'receiver_side':
            for s in (-1, 1): T.box(((A['x0'] + A['x1']) / 2 + 0.02, s * (w / 2 + 0.0008), A['zmid'] + 0.012), ((A['x1'] - A['x0']) * 0.5, 0.0016, 0.006), glow)
        elif a == 'receiver_top':
            T.box(((A['x0'] + A['x1']) / 2, 0, A['z_top'] + 0.0006), ((A['x1'] - A['x0']) * 0.6, 0.006, 0.0016), glow)
        elif a == 'handguard_side':
            for s in (-1, 1): T.box(((A['hg_x0'] + A['hg_x1']) / 2 + 0.01, s * (A['hg_w'] + 0.0006), A['hg_zmid'] + 0.002), (max(0.02, A['hg_x1'] - A['hg_x0'] - 0.06), 0.0016, 0.006), glow)
        elif a == 'magazine_window' and 'mag_mid' in A:
            x, z, rot, mw = A['mag_mid']
            for s in (-1, 1): T.box((x, s * (mw / 2 + 0.0006), z), (0.008, 0.0016, 0.07), glow, rot=(0, rot, 0))
        elif a == 'stock_side' and A.get('stock_len', 0) > 0:
            for s in (-1, 1): T.box((-A['stock_len'] * 0.5, s * 0.0215, 0.0), (A['stock_len'] * 0.5, 0.0016, 0.006), glow)
        elif a == 'barrel_ring':
            T.cyl((A['muzzle_x'] - 0.03, 0, 0), g(A.get('_b'), 'radius', 0.0115) * 1.5, 0.006, glow, seg=16)
        elif a in ACCENTS:
            pass  # valid accent whose anchor this combination does not have (e.g. stock_side with no stock)
        else:
