SELFTEST = [
    {'receiver': {'style': 'ak_stamped'}, 'grip': {'style': 'ak_slanted'}, 'magazine': {'style': 'curved'}, 'stock': {'style': 'fixed_wood'}, 'handguard': {'style': 'wood_ak'}, 'barrel': {'profile': 'tapered', 'muzzle': 'brake'}, 'gas_tube': True, 'sights': {'front': 'hooded', 'rear': 'tangent'}, 'accents': ACCENTS},
    {'receiver': {'style': 'modern_slab'}, 'grip': {'style': 'raked_poly'}, 'magazine': {'style': 'drum'}, 'stock': {'style': 'fixed_poly'}, 'handguard': {'style': 'rail_quad'}, 'barrel': {'profile': 'heavy', 'muzzle': 'flash_hider'}, 'sights': {'front': 'post', 'rear': 'red_dot'}, 'accents': ['receiver_top', 'barrel_ring']},
    {'receiver': {'style': 'smg_boxy'}, 'grip': {'style': 'vertical'}, 'magazine': {'style': 'straight_box'}, 'stock': {'style': 'folding_strut', 'folded': True}, 'handguard': {'style': 'ribbed_shroud'}, 'barrel': {'profile': 'shrouded', 'muzzle': 'suppressor'}, 'sights': {'front': 'none', 'rear': 'notch'}},
    {'receiver': {'style': 'bullpup_shell'}, 'grip': {'style': 'raked_poly'}, 'magazine': {'style': 'straight_box'}, 'stock': {'style': 'bullpup_integral'}, 'handguard': {'style': 'slim_poly'}, 'barrel': {'profile': 'plain', 'muzzle': 'none'}, 'sights': {'rear': 'carry_handle'}, 'accents': ['handguard_side', 'magazine_window', 'stock_side']},
    {'receiver': {'style': 'ak_stamped'}, 'grip': {'style': 'none'}, 'magazine': {'style': 'curved'}, 'stock': {'style': 'folding_wire', 'folded': True}, 'handguard': {'style': 'none'}, 'sights': {'rear': 'none'}},
    {'stock': {'style': 'none'}},
]

