# tpl_crate.py -- PARAMETRIC CRATE / PROP-BOX TEMPLATE (rung 1). New for meshgen (proves the template interface is
# not rifle-specific). Shape language taken from the PoC 1 sci-fi crate (crate_r3.py) and generalised.
# Frame: Z up, base on z=0, length along X, width along Y, metres. Model writes only `spec`.
from mg_geo import Part, make_materials, finish

TEMPLATE_ID = 'crate'
VERSION = 1
SLOTS = ['hull', 'frame', 'panel', 'accent', 'glow', 'dark']
STYLE_PAL = {
    'scifi': {'hull': ('#3f5550', 0.6, 0.5, 0), 'frame': ('#2a2f35', 0.9, 0.35, 0), 'panel': ('#5a6e66', 0.5, 0.45, 0),
              'accent': ('#e8a10c', 0.2, 0.5, 0), 'glow': ('#1f7bff', 0.0, 0.3, 6.0), 'dark': ('#0e1012', 0.3, 0.7, 0)},
    'military': {'hull': ('#4b5634', 0.2, 0.7, 0), 'frame': ('#2e3324', 0.6, 0.5, 0), 'panel': ('#5c6840', 0.2, 0.7, 0),
                 'accent': ('#d9c27a', 0.0, 0.6, 0), 'glow': ('#ff9a1f', 0.0, 0.3, 4.0), 'dark': ('#15170f', 0.2, 0.8, 0)},
    'wooden': {'hull': ('#6e4a2a', 0.0, 0.75, 0), 'frame': ('#3a3b3d', 0.85, 0.45, 0), 'panel': ('#8a5f38', 0.0, 0.7, 0),
               'accent': ('#b8892d', 0.7, 0.4, 0), 'glow': ('#ffcf5a', 0.0, 0.3, 3.0), 'dark': ('#1e140c', 0.0, 0.9, 0)},
}
DEFAULT_PAL = STYLE_PAL['scifi']
VIEWS = [(35, 25, 1.0), (90, 12, 1.0), (215, 30, 1.0)]  # 3/4 front, end, 3/4 back
PART_NAMES = ['body', 'frame', 'panels', 'lid', 'hardware', 'trim']
ENUMS = {
    'style': ('scifi', 'military', 'wooden'), 'lid': ('flat', 'inset', 'ribbed', 'none'),
    'corners': ('caps', 'posts', 'bands', 'none'), 'sides': ('ribbed', 'panels', 'slats', 'plain'),
    'handles': ('bar', 'recessed', 'none'), 'feet': ('blocks', 'skids', 'none'),
}
GLOW = ('front', 'back', 'lid', 'ends')


def _enum(spec, k):
    v = spec.get(k, ENUMS[k][0])
    if v not in ENUMS[k]:
        raise ValueError(f'{k}={v!r} not in {list(ENUMS[k])}')
    return v


def build(spec):
    st = _enum(spec, 'style'); lid = _enum(spec, 'lid'); corners = _enum(spec, 'corners'); sides = _enum(spec, 'sides')
    handles = _enum(spec, 'handles'); feet = _enum(spec, 'feet')
    sz = spec.get('size', {}); L = float(sz.get('length', 1.0)); W = float(sz.get('width', 0.6)); H = float(sz.get('height', 0.6))
    latches = int(spec.get('latches', 2)); label = bool(spec.get('label', st != 'wooden')); glow = spec.get('glow', [])
    for gpos in glow:
        if gpos not in GLOW: raise ValueError(f'glow {gpos!r} not in {list(GLOW)}')
    if not (0 <= latches <= 4): raise ValueError('latches must be 0..4')
    P = {n: Part(n, SLOTS) for n in PART_NAMES}
    B, F, PN, LD, HW, T = (P[n] for n in PART_NAMES)
    m = min(L, W, H); fh = 0.05 * m / 0.6 if feet != 'none' else 0.0   # foot height scales with the crate
    bh = H - fh; zc = fh + bh / 2; t = 0.065 * m                         # frame thickness
    bev = 0.012 * m / 0.6
    B.box((0, 0, zc), (L, W, bh), 'hull', bev)
    # corners
    for sx in (-1, 1):
        for sy in (-1, 1):
            cx, cy = sx * (L / 2 - t / 2 + 0.004 * m), sy * (W / 2 - t / 2 + 0.004 * m)
            if corners in ('posts', 'caps'):
                F.box((cx, cy, zc), (t + 0.008 * m, t + 0.008 * m, bh), 'frame', bev)
            if corners == 'caps':
                for z in (fh + 0.075 * m, H - 0.075 * m):
                    F.box((sx * (L / 2 - 0.075 * m), sy * (W / 2 - 0.075 * m), z), (0.165 * m, 0.165 * m, 0.15 * m), 'frame', 0.025 * m)
    if corners == 'bands':
        for z in (fh + 0.12 * bh, H - 0.12 * bh):
            F.box((0, 0, z), (L + 0.014 * m, W + 0.014 * m, 0.04 * m), 'frame', 0.004 * m)
        for x in (-L / 2 + 0.1 * L, L / 2 - 0.1 * L):
            F.box((x, 0, zc), (0.04 * m, W + 0.016 * m, bh + 0.004 * m), 'frame', 0.004 * m)
    # side treatment on the four faces
    face_h = bh - 0.4 * m if corners == 'caps' else bh - 0.12 * m
    for sy in (-1, 1):  # long faces (normal +-Y)
        y = sy * (W / 2 + 0.006 * m)
        if sides in ('ribbed', 'panels'):
            for sx in ((-1, 1) if L > 0.6 else (0,)):
                px = sx * L * 0.235 if L > 0.6 else 0.0; pw = L * 0.38 if L > 0.6 else L * 0.7
                PN.box((px, y, zc - 0.03 * m), (pw, 0.014 * m, face_h), 'panel', 0.006 * m)
                if sides == 'ribbed':
                    for k in (-1, 0, 1):
                        PN.box((px, sy * (W / 2 + 0.016 * m), zc - 0.03 * m + k * face_h * 0.28), (pw * 0.84, 0.012 * m, 0.04 * m), 'hull', 0.004 * m)
        elif sides == 'slats':
            n = max(3, int(bh / (0.11 * m)))
            for k in range(n):
                z = fh + (k + 0.5) * bh / n
                PN.box((0, y, z), (L - 2 * t, 0.018 * m, bh / n * 0.82), 'panel', 0.004 * m)
        if label:
            T.box((0, sy * (W / 2 + 0.012 * m), zc - 0.03 * m), (min(0.13, L * 0.13), 0.012 * m, min(0.16, face_h * 0.5)), 'accent', 0.004 * m)
    for sx in (-1, 1):  # end faces (normal +-X)
