              'accent': ('#e8a10c', 0.2, 0.5, 0), 'glow': ('#1f7bff', 0.0, 0.3, 6.0), 'dark': ('#0e1012', 0.3, 0.7, 0)},
    'military': {'hull': ('#4b5634', 0.2, 0.7, 0), 'frame': ('#2e3324', 0.6, 0.5, 0), 'panel': ('#5c6840', 0.2, 0.7, 0),
                 'accent': ('#d9c27a', 0.0, 0.6, 0), 'glow': ('#ff9a1f', 0.0, 0.3, 4.0), 'dark': ('#15170f', 0.2, 0.8, 0)},
    'wooden': {'hull': ('#6e4a2a', 0.0, 0.75, 0), 'frame': ('#3a3b3d', 0.85, 0.45, 0), 'panel': ('#8a5f38', 0.0, 0.7, 0),
               'accent': ('#b8892d', 0.7, 0.4, 0), 'glow': ('#ffcf5a', 0.0, 0.3, 3.0), 'dark': ('#1e140c', 0.0, 0.9, 0)},
}
DEFAULT_PAL = STYLE_PAL['scifi']
VIEWS = [(35, 25, 1.0), (90, 12, 1.0), (215, 30, 1.0)]  # 3/4 front, end, 3/4 back
PART_NAMES = ['body', 'frame', 'panels', 'lid', 'hardware', 'trim']
ENUMS = {
