    for sx in (-1, 1):  # end faces (normal +-X)
        x = sx * (L / 2 + 0.006 * m)
        if sides in ('ribbed', 'panels'):
            PN.box((x, 0, zc - 0.03 * m), (0.014 * m, W - 0.2 * m, face_h), 'panel', 0.006 * m)
        elif sides == 'slats':
            n = max(3, int(bh / (0.11 * m)))
            for k in range(n):
                PN.box((x, 0, fh + (k + 0.5) * bh / n), (0.018 * m, W - 2 * t, bh / n * 0.82), 'panel', 0.004 * m)
        # handles
        hz = zc + 0.1 * bh
        if handles == 'bar':
            HW.box((sx * (L / 2 + 0.055 * m), 0, hz), (0.03 * m, 0.43 * W, 0.03 * m), 'frame', 0.01 * m)
            for sy in (-1, 1):
                HW.box((sx * (L / 2 + 0.028 * m), sy * 0.19 * W, hz), (0.056 * m, 0.03 * m, 0.03 * m), 'frame', 0.008 * m)
        elif handles == 'recessed':
            HW.box((sx * (L / 2 + 0.008 * m), 0, hz), (0.02 * m, 0.4 * W, 0.08 * m), 'dark', 0.006 * m)
            HW.box((sx * (L / 2 + 0.016 * m), 0, hz + 0.03 * m), (0.02 * m, 0.4 * W, 0.02 * m), 'frame', 0.005 * m)
    # lid
    if lid != 'none':
        LD.box((0, 0, H + 0.0175 * m), (L - 0.04 * m, W - 0.04 * m, 0.035 * m), 'frame', 0.008 * m)
        F.box((0, 0, H - 0.19 * m), (L + 0.012 * m, W + 0.012 * m, 0.016 * m), 'frame', 0.004 * m)  # lid seam band
        if lid in ('inset', 'ribbed'):
            LD.box((0, 0, H + 0.039 * m), (L - 0.2 * m, W - 0.2 * m, 0.012 * m), 'hull', 0.004 * m)
        if lid == 'ribbed':
            for k in (-1, 0, 1):
                LD.box((k * L * 0.3, 0, H + 0.049 * m), (0.03 * m, W - 0.26 * m, 0.012 * m), 'frame', 0.004 * m)
    # latches on the long faces, evenly spaced
    for i in range(latches):
