        for sy in (-1, 1):
            HW.box((x, sy * (W / 2 + 0.022 * m), H - 0.14 * m), (0.07 * m, 0.03 * m, 0.12 * m), 'frame', 0.01 * m)
            HW.box((x, sy * (W / 2 + 0.042 * m), H - 0.12 * m), (0.03 * m, 0.012 * m, 0.03 * m), 'accent', 0.004 * m)
    # feet
    if feet == 'blocks':
        for sx in (-1, 1):
            for sy in (-1, 1):
                F.box((sx * (L / 2 - 0.07 * m), sy * (W / 2 - 0.07 * m), fh / 2), (0.12 * m, 0.12 * m, fh), 'frame', 0.008 * m)
    elif feet == 'skids':
