# tpl_sword.py -- PARAMETRIC SWORD / MELEE TEMPLATE (rung 1). New for meshgen (second non-rifle template).
# Frame: Z up, blade from z=0 (guard) to z=blade.length, grip below z=0, edge along +X, metres. Model writes only `spec`.
# The blade is ONE lofted closed shell with an 8-vertex lens cross-section whose bevel faces carry the `edge` slot.
import math
from mg_geo import Part, make_materials, finish

TEMPLATE_ID = 'sword'
VERSION = 1
SLOTS = ['blade', 'edge', 'guard', 'grip', 'pommel', 'accent', 'glow', 'dark']
DEFAULT_PAL = {
    'blade': ('#b9c0c8', 0.95, 0.28, 0), 'edge': ('#e6ebf0', 1.0, 0.15, 0), 'guard': ('#8a6a2a', 0.9, 0.35, 0),
    'grip': ('#3b2416', 0.0, 0.7, 0), 'pommel': ('#8a6a2a', 0.9, 0.35, 0), 'accent': ('#c9a13a', 0.9, 0.3, 0),
    'glow': ('#7a3cff', 0.0, 0.3, 6.0), 'dark': ('#1a1c1f', 0.6, 0.5, 0)}
VIEWS = [(90, 4, 0.72), (35, 20, 0.8), (0, 10, 0.72)]  # broadside, 3/4, edge-on
PART_NAMES = ['blade', 'guard', 'grip', 'pommel', 'trim']
ENUMS = {
    'blade.style': ('straight', 'leaf', 'curved', 'cleaver', 'katana'), 'blade.tip': ('point', 'clip', 'square'),
    'guard.style': ('cross', 'disc', 'swept', 'none'), 'pommel.style': ('round', 'disc', 'spike', 'none'),
}
GLOW = ('edge', 'fuller', 'guard', 'pommel')
SINGLE_EDGED = ('curved', 'cleaver', 'katana')


def _enum(S, key, k, default):
    v = (S or {}).get(k, default)
    if v not in ENUMS[f'{key}.{k}']:
        raise ValueError(f'{key}.{k}={v!r} not in {list(ENUMS[key + "." + k])}')
    return v


def _width(style, s):
    if style == 'leaf': return 0.75 + 0.45 * math.sin(math.pi * min(s / 0.8, 1.0)) if s < 0.8 else 1.2 * (1 - (s - 0.8) / 0.2) + 0.15
    if style == 'cleaver': return 1.0 + 0.6 * s
    if style == 'katana': return 1.0 - 0.15 * s
    if style == 'curved': return 1.0 - 0.1 * s
    return 1.0 - 0.12 * s  # straight


def build(spec):
    BS = spec.get('blade', {}); GS = spec.get('guard', {}); HS = spec.get('grip', {}); PS = spec.get('pommel', {})
    style = _enum(BS, 'blade', 'style', 'straight'); tip = _enum(BS, 'blade', 'tip', 'square' if style == 'cleaver' else 'point')
    gst = _enum(GS, 'guard', 'style', 'disc' if style == 'katana' else 'cross'); pst = _enum(PS, 'pommel', 'style', 'none' if style == 'katana' else 'round')
    glow = spec.get('glow', [])
    for gl in glow:
        if gl not in GLOW: raise ValueError(f'glow {gl!r} not in {list(GLOW)}')
    Lb = float(BS.get('length', 0.8)); wb = float(BS.get('width', 0.05)) / 2; tb = float(BS.get('thickness', 0.008)) / 2
    curve = float(BS.get('curve', 0.06 if style in ('curved', 'katana') else 0.0)); fuller = bool(BS.get('fuller', style in ('straight', 'leaf')))
    Lg = float(HS.get('length', 0.2)); rg = float(HS.get('radius', 0.016))
    P = {n: Part(n, SLOTS) for n in PART_NAMES}
    # ---- blade: stations along z, lens section with edge bevels
    N = 14; secs = []; z_end = Lb * (0.9 if tip == 'point' else 0.88 if tip == 'clip' else 1.0)
    for i in range(N):
        s = i / (N - 1); z = s * z_end; w = wb * _width(style, s * z_end / Lb); tt = tb * (1 - 0.55 * s)
        xo = -curve * (z / Lb) ** 2; e = 0.24 * w
        pts = [(-w, 0), (-w + e, tt * 0.45), (0, tt), (w - e, tt * 0.45), (w, 0), (w - e, -tt * 0.45), (0, -tt), (-w + e, -tt * 0.45)]
        secs.append([(xo + x, y, z) for x, y in pts])
    edges = {3, 4} if style in SINGLE_EDGED else {0, 3, 4, 7}
    xo_t = -curve; w_t = wb * _width(style, 1.0)
    apex = None
    if tip == 'point': apex = (xo_t + (0.35 * w_t if style in SINGLE_EDGED else 0.0), 0, Lb)
    elif tip == 'clip': apex = (xo_t + 0.6 * w_t, 0, Lb)
    edge_slot = 'glow' if 'edge' in glow else 'edge'
    P['blade'].loft(secs, 'blade', face_slots=lambda k, i: edge_slot if i in edges else 'blade', tip=apex)
    if fuller:
        for sy in (-1, 1):
            P['trim'].box((-curve * 0.1, sy * tb * 0.86, Lb * 0.36), (wb * 0.22, tb * 0.3, Lb * 0.55), 'glow' if 'fuller' in glow else 'dark')
    # ---- guard
    gw = float(GS.get('width', 0.2 if gst != 'disc' else 0.085)); G = P['guard']
    if gst == 'cross':
        G.box((0, 0, -0.012), (gw, max(0.026, tb * 5), 0.024), 'guard', 0.004)
        for sx in (-1, 1): G.sphere((sx * gw / 2, 0, -0.012), 0.017, 'guard', seg=12, rings=8)
    elif gst == 'disc':
        G.cyl((0, 0, -0.006), gw / 2, 0.012, 'guard', axis='z', seg=24, bevel=0.002)
    elif gst == 'swept':
        G.box((0, 0, -0.012), (0.06, max(0.026, tb * 5), 0.03), 'guard', 0.004)
        for sx in (-1, 1):
            G.rod((sx * 0.02, 0, -0.012), (sx * gw / 2, 0, 0.045), 0.011, 'guard', seg=10)
            G.sphere((sx * gw / 2, 0, 0.045), 0.014, 'guard', seg=10, rings=6)
    if 'guard' in glow and gst != 'none':
        for sy in (-1, 1): P['trim'].sphere((0, sy * max(0.014, tb * 2.6), -0.012), 0.009, 'glow', seg=10, rings=6)
    # ---- grip (+ optional wrap rings)
    Hd = P['grip']; Hd.cyl((0, 0, -Lg / 2 - 0.024 if gst != 'none' else -Lg / 2), rg, Lg, 'grip', axis='z', seg=14)
    z0 = -0.024 if gst != 'none' else 0.0
    if HS.get('wrap', True):
        n = max(3, int(Lg / 0.028))
        for k in range(n): Hd.cyl((0, 0, z0 - (k + 0.5) * Lg / n), rg * 1.07, Lg / n * 0.35, 'accent', axis='z', seg=14)
    zp = z0 - Lg
    # ---- pommel
    Pm = P['pommel']; pr = float(PS.get('size', 0.028))
    if pst == 'round': Pm.sphere((0, 0, zp - pr * 0.7), pr, 'pommel', seg=16, rings=10)
