    # ---- pommel
    Pm = P['pommel']; pr = float(PS.get('size', 0.028))
    if pst == 'round': Pm.sphere((0, 0, zp - pr * 0.7), pr, 'pommel', seg=16, rings=10)
    elif pst == 'disc': Pm.cyl((0, 0, zp - pr * 0.35), pr * 1.1, pr * 0.7, 'pommel', axis='z', seg=20, bevel=0.003)
    elif pst == 'spike': Pm.cyl((0, 0, zp - pr), pr * 0.8, pr * 2, 'pommel', axis='z', r2=0.002, seg=12, rot=(math.pi, 0, 0))
    if 'pommel' in glow and pst != 'none': P['trim'].sphere((0, 0, zp - pr * 0.7), pr * 0.45, 'glow', seg=10, rings=6, scale=(1, 1.9, 1))
    mats = make_materials(SLOTS, DEFAULT_PAL, spec.get('palette'))
    return finish(P, mats)


