    {'blade': {'style': 'straight', 'tip': 'point'}, 'guard': {'style': 'cross'}, 'pommel': {'style': 'round'}},
    {'blade': {'style': 'leaf', 'tip': 'clip', 'length': 0.6}, 'guard': {'style': 'swept'}, 'pommel': {'style': 'spike'}, 'glow': ['fuller', 'guard', 'pommel']},
    {'blade': {'style': 'curved'}, 'guard': {'style': 'disc'}, 'pommel': {'style': 'disc'}, 'grip': {'wrap': False}},
    {'blade': {'style': 'cleaver', 'width': 0.12, 'length': 0.4}, 'guard': {'style': 'none'}, 'pommel': {'style': 'none'}, 'glow': ['edge']},
    {'blade': {'style': 'katana', 'length': 0.7, 'width': 0.032}, 'grip': {'length': 0.26}},
]

