# mg_kit.py -- PARTS-KIT ASSEMBLY (rung 2). The model writes a JSON list of kit parts (shape variants + placement);
# this fixed code turns it into geometry. No model-written code runs. Used when no template fits a hard-surface prop
# (lantern, barrel, terminal, table...). Frame: Z up, metres, rotations in degrees (XYZ Euler).
import math
from mg_geo import Part, make_materials, finish

KIT_ID = 'hardsurface'
VERSION = 1
SLOTS = ['body', 'trim', 'metal', 'wood', 'accent', 'glow', 'dark']
DEFAULT_PAL = {
    'body': ('#4a5058', 0.6, 0.45, 0), 'trim': ('#2b2f35', 0.8, 0.4, 0), 'metal': ('#9aa1aa', 0.95, 0.3, 0),
    'wood': ('#6e4a2a', 0.0, 0.7, 0), 'accent': ('#e0a020', 0.2, 0.5, 0), 'glow': ('#22c8ff', 0.0, 0.3, 6.0), 'dark': ('#0e1013', 0.3, 0.7, 0)}
VIEWS = [(35, 25, 1.0), (0, 8, 1.0), (215, 35, 1.0)]
SHAPES = ('box', 'cylinder', 'tube', 'sphere', 'rod', 'prism', 'wedge', 'ribbed_panel', 'handle', 'strip')
MAX_GROUPS = 12
MAX_PRIMS = 600  # after mirror/array expansion
LIM = 5.0        # every coordinate and size within +-5 m


def _num(v, what, lo=-LIM, hi=LIM):
    if not isinstance(v, (int, float)) or isinstance(v, bool) or not (lo <= float(v) <= hi):
        raise ValueError(f'{what} must be a number in [{lo}, {hi}]')
    return float(v)


def _vec(v, what, n=3, lo=-LIM, hi=LIM):
    if not isinstance(v, (list, tuple)) or len(v) != n:
        raise ValueError(f'{what} must be a list of {n} numbers')
    return tuple(_num(x, what, lo, hi) for x in v)


def _rot(p):
    r = _vec(p.get('rot', [0, 0, 0]), 'rot', lo=-360, hi=360)
    return tuple(math.radians(a) for a in r)


def _emit(part, p, at, rot):
    sh = p['shape']; slot = p.get('slot', 'glow' if sh == 'strip' else 'body'); bev = _num(p.get('bevel', 0.0), 'bevel', 0, 0.2)
    seg = int(_num(p.get('segments', 16), 'segments', 3, 48)); axis = p.get('axis', 'z')
    if axis not in ('x', 'y', 'z'): raise ValueError("axis must be 'x', 'y' or 'z'")
    if sh in ('box', 'strip'):
        part.box(at, _vec(p['size'], 'size', lo=0.0005), slot, bev, rot)
    elif sh == 'cylinder':
        r2 = p.get('radius2'); part.cyl(at, _num(p['radius'], 'radius', 0.0005), _num(p['length'], 'length', 0.0005), slot, axis=axis, r2=None if r2 is None else _num(r2, 'radius2', 0.0), seg=seg, bevel=bev, rot=rot)
    elif sh == 'tube':
        part.tube(at, _num(p['radius'], 'radius', 0.001), _num(p['inner'], 'inner', 0.0005), _num(p['length'], 'length', 0.0005), slot, axis=axis, seg=seg, rot=rot)
    elif sh == 'sphere':
        sc = _vec(p.get('scale', [1, 1, 1]), 'scale', lo=0.05, hi=20)
        part.sphere(at, _num(p['radius'], 'radius', 0.0005), slot, seg=seg, rings=max(4, seg // 2), scale=sc)
    elif sh == 'rod':
        a = _vec(p['from'], 'from'); b = _vec(p['to'], 'to')
        part.rod(tuple(at[i] + a[i] for i in range(3)), tuple(at[i] + b[i] for i in range(3)), _num(p['radius'], 'radius', 0.0005), slot, seg=seg)
    elif sh in ('prism', 'wedge'):
        if sh == 'wedge':
            sx, sy, sz = _vec(p['size'], 'size', lo=0.0005); pts = [(-sx / 2, -sz / 2), (sx / 2, -sz / 2), (-sx / 2, sz / 2)]; depth = sy; plane = 'xz'
        else:
            raw = p['points']
            if not isinstance(raw, list) or not (3 <= len(raw) <= 32): raise ValueError('prism points: 3..32 [a, b] pairs')
            pts = [_vec(q, 'points[]', n=2) for q in raw]; depth = _num(p['depth'], 'depth', 0.0005); plane = p.get('plane', 'xz')
            if plane not in ('xz', 'yz', 'xy'): raise ValueError("plane must be 'xz', 'yz' or 'xy'")
        from mg_geo import _M
        M = _M(at, rot)
        if plane == 'yz':  # centre the extrusion on the placement point
            part.prism(pts, depth, slot, bev, plane=plane, c=-depth / 2, M=M)
        else:
            part.prism(pts, depth, slot, bev, plane=plane, c=0.0, M=M)
    elif sh == 'ribbed_panel':
        sx, sy, sz = _vec(p['size'], 'size', lo=0.0005); n = int(_num(p.get('ribs', 3), 'ribs', 1, 12)); rib_slot = p.get('rib_slot', 'trim')
        part.box(at, (sx, sy, sz), slot, bev, rot)
        from mathutils import Euler, Vector
        R = Euler(rot, 'XYZ').to_matrix()
        for k in range(n):  # ribs across the panel's largest face, proud by its thickness
            off = Vector((0, sy * 0.9, -sz / 2 + (k + 0.5) * sz / n)) if sy <= min(sx, sz) else Vector((-sx / 2 + (k + 0.5) * sx / n, 0, sz * 0.9))
            sz_rib = (sx * 0.86, sy, min(0.04, sz / n * 0.4)) if sy <= min(sx, sz) else (min(0.04, sx / n * 0.4), sy * 0.86, sz)
            part.box(tuple(Vector(at) + R @ off), sz_rib, rib_slot, min(bev, 0.004), rot)
    elif sh == 'handle':
        w = _num(p['width'], 'width', 0.005); h = _num(p.get('height', w * 0.4), 'height', 0.002); t = _num(p.get('thickness', 0.02), 'thickness', 0.002)
        from mathutils import Euler, Vector
        R = Euler(rot, 'XYZ').to_matrix()
        for off, dim in (((0, h, 0), (w, t, t)), ((-w / 2 + t / 2, h / 2, 0), (t, h, t)), ((w / 2 - t / 2, h / 2, 0), (t, h, t))):
            part.box(tuple(Vector(at) + R @ Vector(off)), dim, slot, min(bev, t * 0.3), rot)
    else:
        raise ValueError(f'shape {sh!r} not in {list(SHAPES)}')


def _expand(p):
    """mirror ('x'|'y'|'z'|'xy'|'xz'|'yz'|'xyz') and array {count, step} -> list of (at, rot) placements."""
    at0 = _vec(p.get('at', [0, 0, 0]), 'at'); rot = _rot(p); out = [(at0, rot)]
    arr = p.get('array')
    if arr:
        n = int(_num(arr.get('count', 1), 'array.count', 1, 64)); st = _vec(arr.get('step', [0, 0, 0]), 'array.step')
        out = [(tuple(at0[i] + st[i] * k for i in range(3)), rot) for k in range(n)]
    mir = p.get('mirror')
    if mir:
        if not isinstance(mir, str) or not set(mir) <= set('xyz'): raise ValueError("mirror must use only 'x', 'y', 'z'")
        for ax in sorted(set(mir)):
            i = 'xyz'.index(ax); extra = []
            for a, r in out:
                b = list(a); b[i] = -b[i]
                # mirroring a rotation: negate the two angles that are not about the mirror axis
                rr = list(r)
                for j in range(3):
                    if j != i: rr[j] = -rr[j]
                extra.append((tuple(b), tuple(rr)))
            out = out + extra
    return out


def build(spec):
    parts = spec.get('parts')
    if not isinstance(parts, list) or not (1 <= len(parts) <= 160): raise ValueError('parts: 1..160 entries')
    groups = {}; prims = 0
    for i, p in enumerate(parts):
        if not isinstance(p, dict) or p.get('shape') not in SHAPES: raise ValueError(f'parts[{i}].shape must be one of {list(SHAPES)}')
        gname = p.get('group', 'body')
        if not isinstance(gname, str) or not gname.replace('_', '').isalnum() or len(gname) > 24: raise ValueError(f'parts[{i}].group must be a short identifier')
        if gname not in groups:
            if len(groups) >= MAX_GROUPS: raise ValueError(f'at most {MAX_GROUPS} groups')
            groups[gname] = Part(gname, SLOTS)
        for at, rot in _expand(p):
            prims += 1
            if prims > MAX_PRIMS: raise ValueError(f'more than {MAX_PRIMS} primitives after mirror/array expansion')
            try:
                _emit(groups[gname], p, at, rot)
            except (KeyError, TypeError) as e:
                raise ValueError(f'parts[{i}] ({p.get("shape")}): missing or bad field {e}')
    mats = make_materials(SLOTS, DEFAULT_PAL, spec.get('palette'))
    return finish(groups, mats)


SELFTEST = [
    {'parts': [  # every shape once, with mirror and array
        {'shape': 'box', 'group': 'base', 'at': [0, 0, 0.05], 'size': [0.4, 0.4, 0.1], 'bevel': 0.01, 'slot': 'trim'},
        {'shape': 'cylinder', 'group': 'body', 'at': [0, 0, 0.3], 'radius': 0.12, 'length': 0.4, 'segments': 20},
        {'shape': 'cylinder', 'group': 'body', 'at': [0, 0, 0.55], 'radius': 0.14, 'radius2': 0.04, 'length': 0.1, 'slot': 'metal'},
        {'shape': 'tube', 'group': 'body', 'at': [0, 0, 0.3], 'radius': 0.135, 'inner': 0.122, 'length': 0.02, 'slot': 'accent', 'array': {'count': 3, 'step': [0, 0, 0.12]}},
        {'shape': 'sphere', 'group': 'top', 'at': [0, 0, 0.65], 'radius': 0.04, 'slot': 'glow'},
        {'shape': 'rod', 'group': 'top', 'at': [0, 0, 0.6], 'from': [-0.1, 0, 0], 'to': [0, 0, 0.12], 'radius': 0.008, 'mirror': 'x', 'slot': 'metal'},
        {'shape': 'prism', 'group': 'base', 'at': [0.2, 0, 0.1], 'points': [[0, 0], [0.08, 0], [0, 0.08]], 'depth': 0.05, 'mirror': 'xy'},
        {'shape': 'wedge', 'group': 'base', 'at': [0, 0.22, 0.05], 'size': [0.1, 0.04, 0.08], 'rot': [0, 0, 90], 'mirror': 'y'},
        {'shape': 'ribbed_panel', 'group': 'body', 'at': [0, -0.125, 0.3], 'size': [0.12, 0.01, 0.25], 'ribs': 4, 'slot': 'body'},
        {'shape': 'handle', 'group': 'top', 'at': [0, 0, 0.7], 'width': 0.16, 'height': 0.08, 'thickness': 0.012, 'rot': [90, 0, 0], 'slot': 'trim'},
        {'shape': 'strip', 'group': 'body', 'at': [0, -0.135, 0.42], 'size': [0.08, 0.004, 0.01]},
    ]},
]

