# mg_harness.py -- Cyrus meshgen Blender harness (fixed code, run inside the sandbox):
#   blender --background --factory-startup --python-exit-code 3 --python mg_harness.py -- request.json
# Builds the mesh for one request (template / kit / scratch / selftest), adds UVs, measures every object, decimates
# to the triangle budget when allowed, exports glb, re-imports it, renders a contact sheet, and ALWAYS writes
# result.json in the working directory. Every failure is a structured error {stage, type, message}, never silence.
import bpy, bmesh, sys, os, math, time, json, traceback, random
from mathutils import Vector
sys.dont_write_bytecode = True
IN = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, IN)
OUT = os.getcwd(); T0 = time.time()
HARNESS_VERSION = 1
MODULES = {'template': {'rifle': 'tpl_rifle', 'crate': 'tpl_crate', 'sword': 'tpl_sword'}, 'kit': {'hardsurface': 'mg_kit'}}
RESULT = {'v': 1, 'harness': HARNESS_VERSION, 'ok': False, 'blender': bpy.app.version_string, 'timings': {}}


def done(code=0):
    RESULT['timings']['total_s'] = round(time.time() - T0, 2)
    with open(os.path.join(OUT, 'result.json'), 'w') as f: json.dump(RESULT, f)
    sys.stdout.flush(); sys.exit(code)


def fail(stage, typ, msg):
    RESULT['ok'] = False; RESULT['error'] = {'stage': stage, 'type': typ, 'message': str(msg)[:600]}; done(0)


def clear_scene():
    for o in list(bpy.data.objects): bpy.data.objects.remove(o, do_unlink=True)
    for blk in (bpy.data.meshes, bpy.data.materials, bpy.data.lights, bpy.data.cameras, bpy.data.images):
        for b in list(blk): blk.remove(b)


def measure(objs):
    st = {'objects': len(objs), 'tris': 0, 'nonmanifold_edges': 0, 'uv_objs': 0, 'shells': 0, 'degenerate_faces': 0, 'per_obj': []}
    mats = set(); lo = Vector((1e9,) * 3); hi = Vector((-1e9,) * 3)
    for o in objs:
        bm = bmesh.new(); bm.from_mesh(o.data)
        tris = sum(len(f.verts) - 2 for f in bm.faces); nm = sum(1 for e in bm.edges if not e.is_manifold)
        deg = sum(1 for f in bm.faces if f.calc_area() < 1e-10); loose = sum(1 for v in bm.verts if not v.link_faces)
        seen = set(); shells = 0
        for v in bm.verts:
            if v.index in seen: continue
            shells += 1; stk = [v]; seen.add(v.index)
            while stk:
                c = stk.pop()
                for e in c.link_edges:
                    w = e.other_vert(c)
                    if w.index not in seen: seen.add(w.index); stk.append(w)
        used = sorted({f.material_index for f in bm.faces})
        for i in used:
            if i < len(o.data.materials) and o.data.materials[i]: mats.add(o.data.materials[i].name)
        olo = Vector((1e9,) * 3); ohi = Vector((-1e9,) * 3)
        for v in bm.verts:
            co = o.matrix_world @ v.co
            for i in range(3): olo[i] = min(olo[i], co[i]); ohi[i] = max(ohi[i], co[i])
        uv_ok = bool(o.data.uv_layers); uv_oob = 0
        if uv_ok:
            lay = bm.loops.layers.uv.active
            if lay is not None:
                for f in bm.faces:
                    for lp in f.loops:
                        u, w_ = lp[lay].uv
                        if u < -1e-4 or u > 1.0001 or w_ < -1e-4 or w_ > 1.0001: uv_oob += 1
        st['per_obj'].append({'name': o.name, 'tris': tris, 'nonmanifold_edges': nm, 'shells': shells, 'uv': uv_ok, 'uv_out_of_bounds': uv_oob,
                              'degenerate_faces': deg, 'loose_verts': loose, 'materials': len(used),
                              'bbox_m': [round(ohi[i] - olo[i], 4) for i in range(3)] if bm.verts else [0, 0, 0]})
        st['tris'] += tris; st['nonmanifold_edges'] += nm; st['uv_objs'] += uv_ok; st['shells'] += shells; st['degenerate_faces'] += deg
        for i in range(3): lo[i] = min(lo[i], olo[i]); hi[i] = max(hi[i], ohi[i])
        bm.free()
    st['materials'] = len(mats)
    st['bbox_m'] = [round(hi[i] - lo[i], 4) for i in range(3)] if objs else [0, 0, 0]
