    for modname, spec in (('tpl_rifle', {'magazine': {'style': 'belt'}}), ('tpl_crate', {'lid': 'dome'}), ('tpl_sword', {'blade': {'style': 'whip'}}), ('mg_kit', {'parts': [{'shape': 'torus'}]})):
        clear_scene()
        try:
            __import__(modname).build(spec); neg.append({'module': modname, 'raised': False})
        except ValueError as e:
            neg.append({'module': modname, 'raised': True, 'message': str(e)[:160]})
    RESULT['selftest'] = {'cases': cases, 'negative': neg}
    RESULT['ok'] = all(c['ok'] and c['nonmanifold_edges'] == 0 for c in cases) and all(n['raised'] for n in neg)
    done(0)


def main():
    argv = sys.argv[sys.argv.index('--') + 1:]
    try:
        req = json.load(open(argv[0]))
    except Exception as e:
        fail('request', 'bad_request', e)
    if req.get('v') != 1 or not isinstance(req.get('name'), str): fail('request', 'bad_request', 'v must be 1 and name a string')
    RESULT['name'] = req['name']; RESULT['rung'] = req.get('rung')
    clear_scene()
    if req.get('rung') == 'selftest': selftest(req)
    t = time.time(); objs, mod = build_objects(req)
    objs = [o for o in objs if o.type == 'MESH']
    if not objs: fail('build', 'empty', 'the build produced no mesh objects')
    RESULT['timings']['build_s'] = round(time.time() - t, 2)
    t = time.time(); unwrap(objs); RESULT['timings']['uv_s'] = round(time.time() - t, 2)
    st = measure(objs)
    budget = req.get('budget') or {}; mx = budget.get('maxTriangles')
    RESULT['decimated'] = None
    if mx and st['tris'] > mx and budget.get('decimate'):
        before = st['tris']; t = time.time(); ratio = decimate(objs, mx); st = measure(objs)
        RESULT['decimated'] = {'from': before, 'to': st['tris'], 'ratio': round(ratio, 4), 's': round(time.time() - t, 2)}
    RESULT['stats'] = {k: v for k, v in st.items() if not k.startswith('_')}
    t = time.time(); glb = os.path.join(OUT, req['name'] + '.glb')
    try:
        bpy.ops.export_scene.gltf(filepath=glb, export_format='GLB', export_apply=True, export_yup=True, use_selection=False)
    except Exception as e:
        fail('export', 'export_error', e)
    RESULT['timings']['export_s'] = round(time.time() - t, 2)
    RESULT['glb'] = {'file': os.path.basename(glb), 'bytes': os.path.getsize(glb)}
    if req.get('render'):
        t = time.time(); RESULT['renders'], RESULT['sheet'] = render(objs, st, req, mod); RESULT['timings']['render_s'] = round(time.time() - t, 2)
    # re-import the glb into an empty scene: the file must round-trip to the same triangle count
    t = time.time(); clear_scene()
    try:
        bpy.ops.import_scene.gltf(filepath=glb)
        re = [o for o in bpy.data.objects if o.type == 'MESH']
        RESULT['glb'].update(reimport_meshes=len(re), reimport_tris=sum(len(p.vertices) - 2 for o in re for p in o.data.polygons))
    except Exception as e:
        RESULT['glb'].update(reimport_error=str(e)[:300])
    RESULT['timings']['reimport_s'] = round(time.time() - t, 2)
    RESULT['ok'] = True
    done(0)


try:
    main()
except SystemExit:
    raise
except Exception:
    RESULT['ok'] = False; RESULT['error'] = {'stage': 'harness', 'type': 'crash', 'message': traceback.format_exc()[-600:]}
    with open(os.path.join(OUT, 'result.json'), 'w') as f: json.dump(RESULT, f)
    sys.exit(3)

