// Cyrus meshgen (Model Studio layer 4, the AI MESH route): spec schemas.
// The model never writes geometry for rungs 1-2: it writes ONE of these JSON specs and fixed, deterministic code in
// ./blender turns it into a mesh. Rung 3 (scratch) is the only route where the model writes code (see ./scan.ts).
// Pure + client-safe (Zod only). Each schema mirrors the enum checks the Python module repeats inside the sandbox.
import { z } from "zod";

export const MESHGEN_SCHEMA_VERSION = 1 as const;

/** The cost ladder, cheapest first. catalog = reuse a library asset (no mesh is built). */
export const RUNGS = ["catalog", "template", "kit", "scratch"] as const;
export type Rung = (typeof RUNGS)[number];
export const RUNG_INDEX: Readonly<Record<Rung, 0 | 1 | 2 | 3>> = { catalog: 0, template: 1, kit: 2, scratch: 3 };

/** What the prop is for. Routing + budgets read this; it is never trusted to select code. */
export const MESH_CATEGORIES = ["weapon-ranged", "weapon-melee", "container", "prop", "furniture", "vehicle", "character", "creature", "other"] as const;
export type MeshCategory = (typeof MESH_CATEGORIES)[number];

const hex = z.string().regex(/^#[0-9a-fA-F]{6}$/, "colour as #rrggbb");
const unit = (lo: number, hi: number) => z.number().finite().min(lo).max(hi);
/** A palette slot: "#hex" or {color, metal, rough, emit}. */
const SlotZ = z.union([hex, z.strictObject({ color: hex.optional(), metal: unit(0, 1).optional(), rough: unit(0, 1).optional(), emit: unit(0, 20).optional() })]);
const palette = <const S extends readonly [string, ...string[]]>(slots: S) => z.partialRecord(z.enum(slots), SlotZ);

// ---------------------------------------------------------------- rung 1: templates
export const RIFLE_SLOTS = ["body", "furniture", "barrel", "mag", "accent", "glow", "dark"] as const;
export const RifleSpecZ = z.strictObject({
  receiver: z.strictObject({ style: z.enum(["ak_stamped", "modern_slab", "smg_boxy", "bullpup_shell"]).optional(), length: unit(0.15, 0.7).optional(), width: unit(0.03, 0.07).optional(), height: unit(0.04, 0.1).optional(), rail: z.boolean().optional() }).optional(),
  grip: z.strictObject({ style: z.enum(["ak_slanted", "raked_poly", "vertical", "none"]).optional(), length: unit(0.06, 0.2).optional(), rake: unit(0, 0.8).optional(), width: unit(0.03, 0.06).optional(), guard_scale: unit(0.6, 1.5).optional() }).optional(),
  trigger_guard: z.boolean().optional(),
  magazine: z.strictObject({ style: z.enum(["curved", "straight_box", "drum"]).optional(), capacity: z.number().int().min(5).max(100).optional(), curve_deg: unit(0, 80).optional(), cant_deg: unit(-20, 30).optional(), width: unit(0.02, 0.07).optional(), depth: unit(0.01, 0.04).optional(), length: unit(0.05, 0.4).optional(), radius: unit(0.03, 0.12).optional(), arc_length: unit(0.05, 0.4).optional() }).optional(),
  stock: z.strictObject({ style: z.enum(["fixed_wood", "fixed_poly", "folding_wire", "folding_strut", "bullpup_integral", "none"]).optional(), length: unit(0.1, 0.4).optional(), width: unit(0.02, 0.07).optional(), folded: z.boolean().optional() }).optional(),
  handguard: z.strictObject({ style: z.enum(["wood_ak", "rail_quad", "slim_poly", "ribbed_shroud", "none"]).optional(), length: unit(0.08, 0.45).optional(), material: z.enum(["furniture", "body"]).optional() }).optional(),
  barrel: z.strictObject({ length: unit(0.08, 0.8).optional(), radius: unit(0.006, 0.025).optional(), profile: z.enum(["plain", "tapered", "heavy", "shrouded"]).optional(), muzzle: z.enum(["brake", "flash_hider", "suppressor", "none"]).optional(), suppressor_length: unit(0.06, 0.3).optional() }).optional(),
  gas_tube: z.boolean().optional(),
  sights: z.strictObject({ front: z.enum(["post", "hooded", "none"]).optional(), rear: z.enum(["tangent", "notch", "carry_handle", "red_dot", "none"]).optional() }).optional(),
  accents: z.array(z.enum(["receiver_side", "receiver_top", "handguard_side", "magazine_window", "stock_side", "barrel_ring"])).max(6).optional(),
  palette: palette(RIFLE_SLOTS).optional(),
});

export const CRATE_SLOTS = ["hull", "frame", "panel", "accent", "glow", "dark"] as const;
export const CrateSpecZ = z.strictObject({
  style: z.enum(["scifi", "military", "wooden"]).optional(),
  size: z.strictObject({ length: unit(0.2, 3).optional(), width: unit(0.15, 2).optional(), height: unit(0.15, 2).optional() }).optional(),
  lid: z.enum(["flat", "inset", "ribbed", "none"]).optional(),
  corners: z.enum(["caps", "posts", "bands", "none"]).optional(),
  sides: z.enum(["ribbed", "panels", "slats", "plain"]).optional(),
  handles: z.enum(["bar", "recessed", "none"]).optional(),
  latches: z.number().int().min(0).max(4).optional(),
  feet: z.enum(["blocks", "skids", "none"]).optional(),
  label: z.boolean().optional(),
  glow: z.array(z.enum(["front", "back", "lid", "ends"])).max(4).optional(),
  palette: palette(CRATE_SLOTS).optional(),
});

export const SWORD_SLOTS = ["blade", "edge", "guard", "grip", "pommel", "accent", "glow", "dark"] as const;
export const SwordSpecZ = z.strictObject({
  blade: z.strictObject({ style: z.enum(["straight", "leaf", "curved", "cleaver", "katana"]).optional(), tip: z.enum(["point", "clip", "square"]).optional(), length: unit(0.15, 1.6).optional(), width: unit(0.015, 0.2).optional(), thickness: unit(0.003, 0.03).optional(), curve: unit(0, 0.3).optional(), fuller: z.boolean().optional() }).optional(),
  guard: z.strictObject({ style: z.enum(["cross", "disc", "swept", "none"]).optional(), width: unit(0.03, 0.4).optional() }).optional(),
  grip: z.strictObject({ length: unit(0.06, 0.5).optional(), radius: unit(0.008, 0.03).optional(), wrap: z.boolean().optional() }).optional(),
  pommel: z.strictObject({ style: z.enum(["round", "disc", "spike", "none"]).optional(), size: unit(0.01, 0.06).optional() }).optional(),
  glow: z.array(z.enum(["edge", "fuller", "guard", "pommel"])).max(4).optional(),
  palette: palette(SWORD_SLOTS).optional(),
});

// ---------------------------------------------------------------- rung 2: parts-kit assembly
export const KIT_SLOTS = ["body", "trim", "metal", "wood", "accent", "glow", "dark"] as const;
export const KIT_SHAPES = ["box", "cylinder", "tube", "sphere", "rod", "prism", "wedge", "ribbed_panel", "handle", "strip"] as const;
export const KIT_MAX_PARTS = 160;
export const KIT_MAX_GROUPS = 12;
export const KIT_MAX_PRIMS = 600;
const m = (lo = -5, hi = 5) => unit(lo, hi);
const vec3 = (lo = -5, hi = 5) => z.tuple([m(lo, hi), m(lo, hi), m(lo, hi)]);
const KitPartZ = z.strictObject({
  shape: z.enum(KIT_SHAPES),
  group: z.string().regex(/^[a-z][a-z0-9_]{0,23}$/, "group: short lowercase identifier").optional(),
  slot: z.enum(KIT_SLOTS).optional(),
  at: vec3().optional(),
  rot: vec3(-360, 360).optional(),
  bevel: m(0, 0.2).optional(),
  axis: z.enum(["x", "y", "z"]).optional(),
  segments: z.number().int().min(3).max(48).optional(),
  size: vec3(0.0005, 5).optional(),
  radius: m(0.0005, 5).optional(),
  radius2: m(0, 5).optional(),
  inner: m(0.0005, 5).optional(),
  length: m(0.0005, 5).optional(),
  scale: vec3(0.05, 20).optional(),
  from: vec3().optional(),
  to: vec3().optional(),
  points: z.array(z.tuple([m(), m()])).min(3).max(32).optional(),
  depth: m(0.0005, 5).optional(),
  plane: z.enum(["xz", "yz", "xy"]).optional(),
  ribs: z.number().int().min(1).max(12).optional(),
  rib_slot: z.enum(KIT_SLOTS).optional(),
  width: m(0.005, 5).optional(),
  height: m(0.002, 5).optional(),
  thickness: m(0.002, 1).optional(),
  mirror: z.string().regex(/^(?!.*(.).*\1)[xyz]{1,3}$/, "mirror: x, y, z or a combination").optional(),
  array: z.strictObject({ count: z.number().int().min(1).max(64), step: vec3() }).optional(),
});
export type KitPart = z.infer<typeof KitPartZ>;
/** Fields each shape needs (the Python kit raises the same error when one is missing). */
export const KIT_REQUIRED: Readonly<Record<(typeof KIT_SHAPES)[number], readonly (keyof KitPart)[]>> = {
  box: ["size"], strip: ["size"], cylinder: ["radius", "length"], tube: ["radius", "inner", "length"], sphere: ["radius"],
  rod: ["from", "to", "radius"], prism: ["points", "depth"], wedge: ["size"], ribbed_panel: ["size"], handle: ["width"],
};
export const KitSpecZ = z.strictObject({
  parts: z.array(KitPartZ).min(1).max(KIT_MAX_PARTS),
  palette: palette(KIT_SLOTS).optional(),
}).superRefine((s, ctx) => {
  const groups = new Set<string>();
  let prims = 0;
  s.parts.forEach((p, i) => {
    groups.add(p.group ?? "body");
    for (const f of KIT_REQUIRED[p.shape]) if (p[f] === undefined) ctx.addIssue({ code: "custom", path: ["parts", i, f], message: `${p.shape} needs ${f}` });
    if (p.shape === "tube" && p.radius !== undefined && p.inner !== undefined && !(p.inner < p.radius)) ctx.addIssue({ code: "custom", path: ["parts", i, "inner"], message: "tube inner must be smaller than radius" });
    prims += (p.array?.count ?? 1) * 2 ** (p.mirror?.length ?? 0);
  });
  if (groups.size > KIT_MAX_GROUPS) ctx.addIssue({ code: "custom", path: ["parts"], message: `at most ${KIT_MAX_GROUPS} groups` });
  if (prims > KIT_MAX_PRIMS) ctx.addIssue({ code: "custom", path: ["parts"], message: `${prims} primitives after mirror/array; the cap is ${KIT_MAX_PRIMS}` });
});
export type KitSpec = z.infer<typeof KitSpecZ>;

// ---------------------------------------------------------------- rung 3: from-scratch script
export const SCRATCH_MAX_CHARS = 24000;
export const SCRATCH_MAX_LINES = 600;
export const ScratchSubmissionZ = z.strictObject({ script: z.string().min(20).max(SCRATCH_MAX_CHARS) });

// ---------------------------------------------------------------- the job request (what the queue carries)
export const MeshBudgetZ = z.strictObject({
  maxTriangles: z.number().int().min(100).max(500_000),
  maxMaterials: z.number().int().min(1).max(64),
  maxObjects: z.number().int().min(1).max(256).optional(),
  maxGlbBytes: z.number().int().min(10_000).max(64 * 1024 * 1024).optional(),
  /** Largest bounding-box edge in metres for this category (a "rifle" 9 m long is a unit bug, not a design). */
  maxExtentM: z.number().min(0.01).max(100).optional(),
  minExtentM: z.number().min(0.001).max(10).optional(),
  /** LOD triangle targets the game wants. meshgen does NOT build LODs yet; a non-empty list yields a warning. */
  lods: z.array(z.number().int().min(10)).max(6).default([]),
  /** Decimate to maxTriangles instead of failing (fails anyway if still over afterwards). */
  decimate: z.boolean().default(true),
});
export type MeshBudget = z.infer<typeof MeshBudgetZ>;

export const TokenUsageZ = z.strictObject({
  inputTokens: z.number().int().min(0),
  outputTokens: z.number().int().min(0),
  cachedInputTokens: z.number().int().min(0).default(0),
  /** Which model round produced this spec (1 = first attempt). */
  round: z.number().int().min(1).max(10),
});
export type TokenUsage = z.infer<typeof TokenUsageZ>;

const id = z.string().regex(/^[a-z][a-z0-9_]{0,47}$/, "lowercase id");
const RequestBaseZ = {
  v: z.literal(MESHGEN_SCHEMA_VERSION),
  assetId: id,
  projectId: z.string().min(1).max(64),
  game: z.string().regex(/^[a-z][a-z0-9-]{1,31}$/),
  category: z.enum(MESH_CATEGORIES),
  prompt: z.string().min(1).max(2000),
  budget: MeshBudgetZ,
  render: z.strictObject({ samples: z.number().int().min(1).max(128).default(32) }).nullable().default({ samples: 32 }),
  /** The router's estimate shown to the user before running, and what the model call really used (from the caller). */
  estimate: z.strictObject({ totalTokens: z.number().int().min(0), dollars: z.number().min(0).nullable() }).optional(),
  usage: TokenUsageZ.optional(),
};
export const MeshgenRequestZ = z.discriminatedUnion("rung", [
  z.strictObject({ ...RequestBaseZ, rung: z.literal("template"), template: z.string().regex(/^[a-z][a-z0-9_]{1,31}$/), spec: z.record(z.string(), z.unknown()) }),
  z.strictObject({ ...RequestBaseZ, rung: z.literal("kit"), kit: z.literal("hardsurface"), spec: z.record(z.string(), z.unknown()) }),
  z.strictObject({ ...RequestBaseZ, rung: z.literal("scratch"), script: z.string().min(20).max(SCRATCH_MAX_CHARS) }),
]);
export type MeshgenRequest = z.infer<typeof MeshgenRequestZ>;
export type MeshgenRequestInput = z.input<typeof MeshgenRequestZ>;

export type SpecIssue = { path: string; code: string; message: string };
export const zodIssues = (e: z.ZodError, prefix = ""): SpecIssue[] =>
  e.issues.map((i) => ({ path: [prefix, ...i.path.map(String)].filter(Boolean).join(".") || "spec", code: "invalid_spec", message: i.message }));

