// Cyrus meshgen: the template + kit registry (rungs 1 and 2). Each entry pairs a Zod spec schema (checked here,
// before any job is queued) with a fixed Python module in ./blender that builds the mesh, a short model-facing
// "spec card" (the only thing the model reads about the template, cacheable) and the routing keywords.
// ADDING A TEMPLATE: docs/DOCUMENTATION.md "Cyrus AI mesh (meshgen)" -> "Adding a template". Pure + client-safe.
import type { z } from "zod";
import { CrateSpecZ, KitSpecZ, RifleSpecZ, SwordSpecZ, zodIssues, type MeshCategory, type SpecIssue } from "./spec";

export type TemplateDef = {
  id: string;
  version: number;
  label: string;
  /** Python module in ./blender (without .py) exposing build(spec), SLOTS, VIEWS, SELFTEST. */
  module: string;
  /** Extra Python files the module imports (shipped with every job). */
  deps: readonly string[];
  categories: readonly MeshCategory[];
  /** Lowercase whole-word keywords; the router scores a prompt by hits. */
  keywords: readonly string[];
  /** Words that mean "this template is the wrong shape" even when a keyword hits ("revolver" is not a rifle). */
  excludes: readonly string[];
  schema: z.ZodType;
  /** What the model is told (<= ~1.2k chars, about 300-400 tokens). */
  card: string;
  /** A valid example spec, also the default when the model sends {} on purpose. */
  example: Record<string, unknown>;
  /** Did a real PoC measure this template's token use? Only the rifle has been (research K-partskit-poc.md). */
  tokenBasis: "measured" | "assumed";
};

const RIFLE_CARD = `Rifle spec JSON (all keys optional; metres; +X muzzle). Output ONLY this JSON.
receiver{style:ak_stamped|modern_slab|smg_boxy|bullpup_shell, length,width,height,rail(bullpup)}
grip{style:ak_slanted|raked_poly|vertical|none, length,rake(rad)}  trigger_guard:bool
magazine{style:curved|straight_box|drum, capacity, curve_deg, cant_deg, width, depth}
stock{style:fixed_wood|fixed_poly|folding_wire|folding_strut|bullpup_integral|none, length, folded:bool}
handguard{style:wood_ak|rail_quad|slim_poly|ribbed_shroud|none, length, material:furniture|body}
barrel{length,radius,profile:plain|tapered|heavy|shrouded, muzzle:brake|flash_hider|suppressor|none, suppressor_length}
gas_tube:bool   sights{front:post|hooded|none, rear:tangent|notch|carry_handle|red_dot|none}
accents[receiver_side|receiver_top|handguard_side|magazine_window|stock_side|barrel_ring]  (glow strips)
palette{body,furniture,barrel,mag,accent,glow,dark: "#hex" | {color,metal,rough,emit}}`;

const CRATE_CARD = `Crate spec JSON (all keys optional; metres; Z up, base on the floor). Output ONLY this JSON.
style:scifi|military|wooden (sets the default palette)   size{length,width,height}
lid:flat|inset|ribbed|none   corners:caps|posts|bands|none   sides:ribbed|panels|slats|plain
handles:bar|recessed|none   latches:0-4   feet:blocks|skids|none   label:bool
glow[front|back|lid|ends]  (emissive strips)
palette{hull,frame,panel,accent,glow,dark: "#hex" | {color,metal,rough,emit}}`;

const SWORD_CARD = `Sword/melee spec JSON (all keys optional; metres; blade points +Z, guard at 0). Output ONLY this JSON.
blade{style:straight|leaf|curved|cleaver|katana, tip:point|clip|square, length,width,thickness, curve(m), fuller:bool}
guard{style:cross|disc|swept|none, width}   grip{length,radius,wrap:bool}   pommel{style:round|disc|spike|none, size}
glow[edge|fuller|guard|pommel]
palette{blade,edge,guard,grip,pommel,accent,glow,dark: "#hex" | {color,metal,rough,emit}}`;

export const TEMPLATES: readonly TemplateDef[] = [
  {
    id: "rifle", version: 1, label: "Rifle / SMG / carbine", module: "tpl_rifle", deps: ["tpl_rifle_parts.py"],
    categories: ["weapon-ranged"],
    keywords: ["rifle", "carbine", "smg", "submachine", "assault", "bullpup", "ak", "kalashnikov", "battle", "marksman", "gun", "firearm", "blaster"],
    excludes: ["pistol", "revolver", "handgun", "shotgun", "sniper", "bolt", "launcher", "rocket", "minigun", "bow", "crossbow", "flamethrower", "belt", "lmg"],
    schema: RifleSpecZ, card: RIFLE_CARD, tokenBasis: "measured",
    example: { receiver: { style: "ak_stamped" }, magazine: { style: "curved", capacity: 30 }, barrel: { length: 0.42, muzzle: "brake", profile: "tapered" }, gas_tube: true, sights: { front: "hooded", rear: "tangent" } },
  },
  {
    id: "crate", version: 1, label: "Crate / prop box", module: "tpl_crate", deps: [],
    categories: ["container", "prop"],
    keywords: ["crate", "box", "chest", "container", "case", "supply", "ammo", "loot", "footlocker", "locker", "trunk", "cargo", "toolbox", "lootbox"],
    excludes: ["barrel", "bag", "sack", "jar", "bottle", "vase", "coffin", "safe", "fridge"],
    schema: CrateSpecZ, card: CRATE_CARD, tokenBasis: "assumed",
    example: { style: "scifi", lid: "ribbed", corners: "caps", sides: "ribbed", handles: "bar", latches: 2, glow: ["front"] },
  },
  {
    id: "sword", version: 1, label: "Sword / blade / melee", module: "tpl_sword", deps: [],
    categories: ["weapon-melee"],
    keywords: ["sword", "blade", "katana", "sabre", "saber", "scimitar", "machete", "cleaver", "dagger", "knife", "longsword", "broadsword", "gladius", "cutlass", "melee"],
    excludes: ["axe", "hammer", "mace", "spear", "halberd", "scythe", "bow", "whip", "flail", "staff", "club"],
    schema: SwordSpecZ, card: SWORD_CARD, tokenBasis: "assumed",
    example: { blade: { style: "straight", tip: "point" }, guard: { style: "cross" }, pommel: { style: "round" } },
  },
];

export const KIT = {
  id: "hardsurface" as const, version: 1, module: "mg_kit", schema: KitSpecZ,
  card: `Hard-surface parts kit JSON. Output ONLY {"parts":[...], "palette":{...}}. Metres, Z up, rot in degrees.
part{shape, group(lowercase id, <=12 groups), slot:body|trim|metal|wood|accent|glow|dark, at[x,y,z], rot[x,y,z], bevel,
 mirror:"x"|"y"|"z"|"xy".., array{count,step[x,y,z]}}
shapes: box{size[x,y,z]} strip{size} (glow) cylinder{radius,length,axis,radius2(cone),segments} tube{radius,inner,length,axis}
 sphere{radius,scale[3]} rod{from[3],to[3],radius} (relative to at) prism{points[[a,b]..],depth,plane:xz|yz|xy} wedge{size}
 ribbed_panel{size,ribs,rib_slot} handle{width,height,thickness}
caps: 160 parts, 600 primitives after mirror/array, coordinates within 5 m.`,
};

export const getTemplate = (id: string): TemplateDef | null => TEMPLATES.find((t) => t.id === id) ?? null;

/** Every Python file a template/kit/scratch job needs (the harness imports by name). */
export function pythonFilesFor(): string[] {
  const s = new Set<string>(["mg_harness.py", "mg_geo.py", "mg_kit.py", "mg_scratch.py"]);
  for (const t of TEMPLATES) { s.add(`${t.module}.py`); for (const d of t.deps) s.add(d); }
  return [...s].sort();
}

export type SpecCheck = { ok: true; spec: Record<string, unknown> } | { ok: false; issues: SpecIssue[] };

/** Validate a model-written spec against its template (or the kit). Never throws. */
export function checkSpec(rung: "template" | "kit", templateId: string | null, raw: unknown): SpecCheck {
  const schema = rung === "kit" ? KIT.schema : getTemplate(templateId ?? "")?.schema;
  if (!schema) return { ok: false, issues: [{ path: "template", code: "unknown_template", message: `no template ${String(templateId)}; known: ${TEMPLATES.map((t) => t.id).join(", ")}` }] };
  const r = schema.safeParse(raw);
  return r.success ? { ok: true, spec: r.data as Record<string, unknown> } : { ok: false, issues: zodIssues(r.error, "spec") };
}

/** Pull the JSON object out of a model reply (tolerates a ```json fence or prose around ONE object). */
export function extractJsonObject(text: string): { ok: true; value: unknown } | { ok: false; message: string } {
  const t = text.trim();
  const fence = /```(?:json)?\s*([\s\S]*?)```/.exec(t);
  const body = fence ? fence[1] : t;
  const a = body.indexOf("{"), b = body.lastIndexOf("}");
  if (a < 0 || b <= a) return { ok: false, message: "no JSON object in the reply" };
  try { return { ok: true, value: JSON.parse(body.slice(a, b + 1)) }; }
  catch (e) { return { ok: false, message: `invalid JSON: ${(e as Error).message}` }; }
}

