shapes: box{size[x,y,z]} strip{size} (glow) cylinder{radius,length,axis,radius2(cone),segments} tube{radius,inner,length,axis}
 sphere{radius,scale[3]} rod{from[3],to[3],radius} (relative to at) prism{points[[a,b]..],depth,plane:xz|yz|xy} wedge{size}
 ribbed_panel{size,ribs,rib_slot} handle{width,height,thickness}
caps: 160 parts, 600 primitives after mirror/array, coordinates within 5 m.`,
};

export const getTemplate = (id: string): TemplateDef | null => TEMPLATES.find((t) => t.id === id) ?? null;

/** Every Python file a template/kit/scratch job needs (the harness imports by name). */
export function pythonFilesFor(): string[] {
  const s = new Set<string>(["mg_harness.py", "mg_geo.py", "mg_kit.py", "mg_scratch.py"]);
  for (const t of TEMPLATES) { s.add(`${t.module}.py`); for (const d of t.deps) s.add(d); }
  return [...s].sort();
}

export type SpecCheck = { ok: true; spec: Record<string, unknown> } | { ok: false; issues: SpecIssue[] };

/** Validate a model-written spec against its template (or the kit). Never throws. */
export function checkSpec(rung: "template" | "kit", templateId: string | null, raw: unknown): SpecCheck {
  const schema = rung === "kit" ? KIT.schema : getTemplate(templateId ?? "")?.schema;
  if (!schema) return { ok: false, issues: [{ path: "template", code: "unknown_template", message: `no template ${String(templateId)}; known: ${TEMPLATES.map((t) => t.id).join(", ")}` }] };
  const r = schema.safeParse(raw);
  return r.success ? { ok: true, spec: r.data as Record<string, unknown> } : { ok: false, issues: zodIssues(r.error, "spec") };
}

/** Pull the JSON object out of a model reply (tolerates a ```json fence or prose around ONE object). */
export function extractJsonObject(text: string): { ok: true; value: unknown } | { ok: false; message: string } {
  const t = text.trim();
  const fence = /```(?:json)?\s*([\s\S]*?)```/.exec(t);
  const body = fence ? fence[1] : t;
  const a = body.indexOf("{"), b = body.lastIndexOf("}");
  if (a < 0 || b <= a) return { ok: false, message: "no JSON object in the reply" };
  try { return { ok: true, value: JSON.parse(body.slice(a, b + 1)) }; }
  catch (e) { return { ok: false, message: `invalid JSON: ${(e as Error).message}` }; }
}

