// Cyrus meshgen rung 0: reuse an asset from the catalog/library instead of making one. This is ONLY the interface
// meshgen needs. The real implementation belongs to the asset catalog (branch feature/cyrus-r14-catalog,
// lib/cyrus/library/v2); it plugs in by implementing CatalogMatcher. The fake below exists for tests. Pure.

export type CatalogCandidate = {
  /** The catalog's own id for the asset. */
  assetId: string;
  title: string;
  /** 0..1 relevance. The router only takes rung 0 at or above its threshold. */
  score: number;
  /** How well the asset fits this game (catalog fit rules); "unknown" never counts as a fit. */
  fit: "good" | "ok" | "unknown" | "none";
  triangles?: number;
  legalClass?: string;
};

export interface CatalogMatcher {
  /** Candidates for a free-text query in one game, best first. Must not throw for "nothing found" (return []). */
  catalogMatch(query: string, game: string, opts?: { category?: string; limit?: number }): Promise<CatalogCandidate[]>;
}

/** No catalog wired: rung 0 is never available. */
export const NO_CATALOG: CatalogMatcher = { catalogMatch: async () => [] };

export const tokenize = (s: string): string[] => s.toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g, " ").trim().split(" ").filter(Boolean);

export type FakeCatalogEntry = { assetId: string; title: string; tags: readonly string[]; games?: readonly string[]; triangles?: number; fit?: CatalogCandidate["fit"] };

/** Deterministic token-overlap matcher for tests: score = matched query words / query words (stop words dropped). */
export function createFakeCatalog(entries: readonly FakeCatalogEntry[]): CatalogMatcher {
  const STOP = new Set(["a", "an", "the", "of", "with", "and", "for", "to", "in", "on", "my", "make", "me", "some", "style"]);
  return {
    async catalogMatch(query, game, opts = {}) {
      const q = [...new Set(tokenize(query).filter((w) => !STOP.has(w)))];
      if (!q.length) return [];
      const out: CatalogCandidate[] = [];
      for (const e of entries) {
        if (e.games && !e.games.includes(game)) continue;
        const words = new Set([...tokenize(e.title), ...e.tags.flatMap(tokenize)]);
        const hits = q.filter((w) => words.has(w)).length;
        if (!hits) continue;
        out.push({ assetId: e.assetId, title: e.title, score: Math.round((hits / q.length) * 1000) / 1000, fit: e.fit ?? "good", triangles: e.triangles, legalClass: "platform-library" });
      }
      out.sort((a, b) => b.score - a.score || a.assetId.localeCompare(b.assetId));
      return out.slice(0, opts.limit ?? 5);
    },
  };
}

