// Cyrus meshgen: token cost model per rung + the money estimate shown BEFORE a job runs.
// Prices are an INPUT (owner settings), never invented here: with no prices configured the estimate is tokens only
// and `dollars` is null. Token numbers come from the 2026-10-10 PoCs (research I-blender-poc.md, K-partskit-poc.md);
// `basis` says which rungs were measured and which are assumptions. Pure + client-safe.
import type { Rung } from "./spec";

/** Tokens one model round costs (one spec/script out, the stats + contact sheet back in). */
export type RoundProfile = {
  /** Cacheable prefix: system prompt + spec card / kit card / scratch prelude docs. */
  cachedInput: number;
  /** Uncached input: the user's prompt, the previous round's stats and issues. */
  input: number;
  /** Model output incl. its reasoning (the JSON spec itself is only ~150 tokens on rung 1). */
  output: number;
  /** The rendered contact sheet the model looks at (vision input). 0 when renders are off. */
  imageInput: number;
};

export type RungTokenProfile = {
  rung: Rung;
  perRound: RoundProfile;
  expectedRounds: number;
  /** Hard cap: the build service never runs more rounds than this for one asset. */
  maxRounds: number;
  /** Hard cap on model output per round (the service passes it as max_tokens). */
  maxOutputPerRound: number;
  basis: "measured" | "assumed";
  /** Measured whole-asset totals, when a PoC measured them. */
  measuredTotal?: readonly [number, number];
  source: string;
};

export const TOKEN_PROFILES: Readonly<Record<Rung, RungTokenProfile>> = {
  catalog: {
    rung: "catalog", perRound: { cachedInput: 0, input: 400, output: 120, imageInput: 0 }, expectedRounds: 1, maxRounds: 1, maxOutputPerRound: 400,
    basis: "assumed", source: "one query + a short candidate list; not measured",
  },
  template: {
    rung: "template", perRound: { cachedInput: 350, input: 350, output: 1050, imageInput: 1100 }, expectedRounds: 2, maxRounds: 3, maxOutputPerRound: 1500,
    basis: "measured", measuredTotal: [5200, 8000],
    source: "K-partskit-poc.md: rifle template, 3 prompts x 2 rounds, 5.2-8.0k tokens per finished prop (session counter + est. image reads)",
  },
  kit: {
    rung: "kit", perRound: { cachedInput: 700, input: 450, output: 1600, imageInput: 1100 }, expectedRounds: 3, maxRounds: 4, maxOutputPerRound: 4000,
    basis: "assumed", source: "not measured: a parts list is 3-6x a template spec (20-40 parts) and needs about one more round",
  },
  scratch: {
    rung: "scratch", perRound: { cachedInput: 300, input: 500, output: 2000, imageInput: 2000 }, expectedRounds: 4, maxRounds: 4, maxOutputPerRound: 8000,
    basis: "measured", measuredTotal: [15000, 20000],
    source: "I-blender-poc.md: crate 3 rounds ~15k, rifle 4 rounds ~20k, ~5k per round with a fixed prelude",
  },
};

/** USD per million tokens. All optional fields fall back to the input price. */
export type MeshgenPrices = { inputPerMTok: number; outputPerMTok: number; cacheReadPerMTok?: number; imagePerMTok?: number };

export const PRICE_SETTING_KEYS = {
  input: "cyrus_meshgen_price_input_per_mtok",
  output: "cyrus_meshgen_price_output_per_mtok",
  cacheRead: "cyrus_meshgen_price_cache_read_per_mtok",
} as const;

/** Prices from host settings. Missing or unparsable input/output -> null (tokens-only estimate). */
export function parsePrices(settings: Readonly<Record<string, string | undefined>>): MeshgenPrices | null {
  const num = (k: string) => { const v = settings[k]; if (v === undefined || v.trim() === "") return null; const n = Number(v); return Number.isFinite(n) && n >= 0 ? n : null; };
  const i = num(PRICE_SETTING_KEYS.input), o = num(PRICE_SETTING_KEYS.output), c = num(PRICE_SETTING_KEYS.cacheRead);
  if (i === null || o === null) return null;
  return c === null ? { inputPerMTok: i, outputPerMTok: o } : { inputPerMTok: i, outputPerMTok: o, cacheReadPerMTok: c };
}

export type TokenTotals = { inputTokens: number; cachedInputTokens: number; outputTokens: number };
export const totalTokens = (t: TokenTotals) => t.inputTokens + t.cachedInputTokens + t.outputTokens;

export function dollarsFor(t: TokenTotals, p: MeshgenPrices | null): number | null {
  if (!p) return null;
  const d = (t.inputTokens * p.inputPerMTok + t.cachedInputTokens * (p.cacheReadPerMTok ?? p.inputPerMTok) + t.outputTokens * p.outputPerMTok) / 1e6;
  return Math.round(d * 1e6) / 1e6;
}

export type CostEstimate = {
  rung: Rung;
  rounds: number;
  maxRounds: number;
  expected: TokenTotals & { totalTokens: number };
  worstCase: TokenTotals & { totalTokens: number };
  dollars: number | null;
  worstCaseDollars: number | null;
  basis: "measured" | "assumed";
  measuredTotal: readonly [number, number] | null;
  notes: string[];
};

function sum(p: RoundProfile, rounds: number, renders: boolean): TokenTotals {
  // Round 1 has no previous image to look at only when renders are off; with renders every round ends with one look.
  const img = renders ? p.imageInput : 0;
  return { inputTokens: (p.input + img) * rounds, cachedInputTokens: p.cachedInput * rounds, outputTokens: p.output * rounds };
}

/** Estimate for one asset on one rung. `renders: false` drops the vision input (blind mode, not recommended). */
export function estimateCost(rung: Rung, opts: { prices?: MeshgenPrices | null; rounds?: number; renders?: boolean } = {}): CostEstimate {
  const prof = TOKEN_PROFILES[rung];
  const rounds = Math.max(1, Math.min(prof.maxRounds, opts.rounds ?? prof.expectedRounds));
  const renders = opts.renders ?? rung !== "catalog";
  const e = sum(prof.perRound, rounds, renders), w = sum(prof.perRound, prof.maxRounds, renders);
  const prices = opts.prices ?? null;
  const notes: string[] = [];
  if (!prices) notes.push("no token prices configured (owner settings), so this is a token estimate only");
  if (prof.basis === "assumed") notes.push(`token use on the ${rung} rung has not been measured yet`);
  if (rung === "scratch") notes.push("from-scratch scripts are the premium route: highest cost, most rounds, most failures");
  return {
    rung, rounds, maxRounds: prof.maxRounds,
    expected: { ...e, totalTokens: totalTokens(e) }, worstCase: { ...w, totalTokens: totalTokens(w) },
    dollars: dollarsFor(e, prices), worstCaseDollars: dollarsFor(w, prices),
    basis: prof.basis, measuredTotal: prof.measuredTotal ?? null, notes,
  };
}

