input.content:
// Cyrus meshgen ROUTER: picks the cheapest rung of the cost ladder that can make the prop, deterministically
// (keywords + category + what is switched on), and attaches the token/money estimate the user sees BEFORE running.
//   0 catalog  -> reuse a library asset (only when a matcher is wired and a candidate clears the threshold)
//   1 template -> the model writes a small JSON spec for a fixed template (rifle, crate, sword, ...)
//   2 kit      -> the model writes a JSON parts list for the hard-surface kit (no code)
//   3 scratch  -> the model writes a Blender script (premium, strictly capped, off unless CYRUS_MESHGEN_SCRATCH=1)
// Characters, creatures and likenesses are refused on every rung. Pure apart from the injected catalog call.
import { tokenize, type CatalogCandidate, type CatalogMatcher } from "./catalog";
import { estimateCost, type CostEstimate, type MeshgenPrices } from "./cost";
import { RUNG_INDEX, type MeshCategory, type Rung } from "./spec";
import { TEMPLATES, type TemplateDef } from "./templates";

/** Never made by meshgen: no rig, and likeness/organic quality is not there (MODEL-STUDIO-PLAN section 8). */
export const REFUSE_WORDS = ["character", "person", "human", "man", "woman", "girl", "boy", "child", "face", "portrait", "selfie", "animal", "dog", "cat", "horse", "dragon", "monster", "zombie", "creature", "npc", "mob", "likeness", "celebrity", "player", "skin", "avatar"] as const;
/** Soft/organic shapes the hard-surface kit cannot express; only the scratch rung may try (and is weak at them). */
export const ORGANIC_WORDS = ["tree", "plant", "flower", "bush", "grass", "rock", "boulder", "stone", "cloth", "fabric", "plush", "organic", "sculpture", "statue", "bust", "mushroom", "food", "fruit", "cake", "hair", "fur", "leaf", "leaves", "coral", "bone", "skull"] as const;
/** Real weapon names: not blocked here, but the community library holds them for review (plan section 9). */
export const REAL_WEAPON_WORDS = ["ak47", "ak74", "m4", "m4a1", "m16", "ar15", "glock", "mp5", "mp7", "famas", "aug", "p90", "uzi", "scar", "g36", "hk416", "kalashnikov", "colt", "beretta", "barrett"] as const;

export type Availability = {
  /** Rung 0. null/undefined = no catalog wired (today). */
  catalog?: CatalogMatcher | null;
  /** Template ids switched on for this game. Default: every registered template. */
  templates?: readonly string[];
  /** Rung 2 on/off. Default on. */
  kit?: boolean;
  /** Rung 3 on/off. Default OFF (CYRUS_MESHGEN_SCRATCH and the plan decide). */
  scratch?: boolean;
};

export type RouteInput = {
  prompt: string;
  game: string;
  category?: MeshCategory;
  availability?: Availability;
  /** The user explicitly asks for a more expensive rung ("make it from scratch"). Never a cheaper one than possible. */
  forceRung?: Rung;
  prices?: MeshgenPrices | null;
  /** Catalog score needed to take rung 0 (default 0.75). */
  catalogThreshold?: number;
};

export type Considered = { rung: Rung; available: boolean; why: string };
export type RouteDecision =
  | { ok: true; rung: Rung; templateId: string | null; candidates: CatalogCandidate[]; reason: string; considered: Considered[]; estimate: CostEstimate; warnings: string[] }
  | { ok: false; code: "refused" | "unavailable" | "bad_request"; reason: string; considered: Considered[]; warnings: string[] };

const hits = (words: Set<string>, list: readonly string[]) => list.filter((w) => words.has(w));

/** Words of the prompt, with "ak-47" / "AK 47" also seen as "ak47". */
export function promptWords(prompt: string): Set<string> {
  const t = tokenize(prompt);
  const s = new Set(t);
  for (let i = 0; i + 1 < t.length; i++) if (/^[a-z]+$/.test(t[i]) && /^[0-9]+[a-z]?[0-9]*$/.test(t[i + 1])) s.add(t[i] + t[i + 1]);
  return s;
}

/** Best template for a prompt: needs >= 1 keyword hit and no exclude hit; category match breaks ties. Deterministic. */
export function matchTemplate(words: Set<string>, category: MeshCategory | undefined, enabled: readonly string[]): { template: TemplateDef; score: number; hits: string[] } | null {
  let best: { template: TemplateDef; score: number; hits: string[] } | null = null;
  for (const t of TEMPLATES) {
    if (!enabled.includes(t.id)) continue;
