// Cyrus meshgen: the mesh budget a job is checked against, resolved from the game's AssetProfile.meshBudget.
// No shipped adapter declares one yet (Minecraft takes no meshes), so tests and the node-2 flights use
// DRAFT_MESH_PROFILE: an explicitly made-up "generic glTF prop" profile whose numbers come from no game's docs.
// A real adapter (FiveM, a UE game) declares its own budget when it is written. Pure.
import type { AssetProfile } from "../adapters/asset-profile";
import { MeshBudgetZ, type MeshBudget, type MeshCategory } from "./spec";

/** Default sizes per category, metres (largest bbox edge). Catches unit bugs (a 9 m rifle), not style. */
export const CATEGORY_EXTENT: Readonly<Record<MeshCategory, [number, number]>> = {
  "weapon-ranged": [0.15, 2.5], "weapon-melee": [0.1, 2.5], container: [0.1, 4], prop: [0.02, 6], furniture: [0.2, 5],
  vehicle: [1, 20], character: [0.3, 4], creature: [0.1, 10], other: [0.01, 10],
};

export const DRAFT_MESH_PROFILE: AssetProfile = {
  game: "gltf-prop-draft",
  engineFamily: "other",
  meshFormats: ["gltf"],
  textureFormats: ["png"],
  compression: ["png"],
  channelMap: { albedo: { file: "<asset>_albedo.png", channels: "rgba" } },
  normalConvention: "opengl",
  colorSpace: { albedo: "srgb" },
  maxTextureRes: 2048,
  // DRAFT: made-up targets for a mid-poly game prop. Not from any engine's documentation.
  meshBudget: { maxTriangles: 10000, maxMaterials: 8, lods: [], maxObjects: 16, maxGlbBytes: 4 * 1024 * 1024, perCategory: { container: { maxTriangles: 8000 }, "weapon-melee": { maxTriangles: 6000 } } },
  uvRules: "new",
  skeletonPolicy: "none",
  packaging: "glb",
  delivery: "none",
  workerClass: "linux-cpu",
  requiredGameFiles: "none",
  legal: { policyUrl: null, commercialOk: "unknown", aiOk: "unknown", redistributeBase: false, attestationRequired: false, retrievedAt: null, reviewed: false },
  validators: ["lib/cyrus/meshgen/checks.ts"],
  previewShader: "pbr",
  maturity: "planned",
};

export type BudgetResolution = { ok: true; budget: MeshBudget } | { ok: false; reason: string };

/** Budget for one category of one game. A profile without meshBudget cannot take meshgen output (fail closed). */
export function resolveBudget(profile: AssetProfile | null | undefined, category: MeshCategory, overrides: { decimate?: boolean } = {}): BudgetResolution {
  if (!profile) return { ok: false, reason: "unknown game" };
  const b = profile.meshBudget;
  if (!b) return { ok: false, reason: `${profile.game} declares no mesh budget, so it takes no AI meshes` };
  const pc = b.perCategory?.[category] ?? {};
  const [minE, maxE] = CATEGORY_EXTENT[category];
  const r = MeshBudgetZ.safeParse({
    maxTriangles: Math.min(b.maxTriangles, pc.maxTriangles ?? b.maxTriangles), maxMaterials: b.maxMaterials, maxObjects: b.maxObjects,
    maxGlbBytes: b.maxGlbBytes, maxExtentM: pc.maxExtentM ?? maxE, minExtentM: pc.minExtentM ?? minE, lods: [...b.lods], decimate: overrides.decimate ?? true,
  });
  return r.success ? { ok: true, budget: r.data } : { ok: false, reason: `invalid mesh budget for ${profile.game}: ${r.error.issues[0]?.message}` };
}

