    if (b.uri !== undefined) issues.push({ code: "gltf_external_uri", message: `buffer ${i} points at an external/data uri; a meshgen glb must be self-contained` });
    else if (i !== 0) issues.push({ code: "gltf_extra_buffer", message: `buffer ${i} without uri; only buffer 0 can live in the BIN chunk` });
