  for (let t = 0; t < tris; t++) pos.set([t, 0, 0, t + 1, 0, 0, t, 1, 0], t * 9);
  const binLen = Math.ceil(pos.byteLength / 4) * 4;
  const mats = Array.from({ length: opts.materials ?? 1 }, (_, i) => ({ name: `m${i}` }));
  const doc = {
    asset: { version: "2.0", generator: "cyrus-meshgen-test" }, scene: 0, scenes: [{ nodes: [0] }], nodes: [{ mesh: 0 }],
    meshes: [{ primitives: [{ attributes: { POSITION: 0 }, material: 0 }] }], materials: mats,
    buffers: [{ byteLength: pos.byteLength }], bufferViews: [{ buffer: 0, byteLength: pos.byteLength }],
    accessors: [{ bufferView: 0, componentType: 5126, count: tris * 3, type: "VEC3", min: [0, 0, 0], max: [tris, 1, 0] }],
    ...opts.extraJson,
  };
