// Cyrus meshgen POST-PROCESSING CHECKS: what the Blender harness measured (result.json) + the independent GLB parse,
// judged against the game's mesh budget. Fails closed: any error-severity issue means the asset is not saved
// (no glb/manifest goes into the store), only the record with these issues and the renders for the next round.
// Pure. The result.json shape is produced by ./blender/mg_harness.py (HARNESS_VERSION 1).
import { z } from "zod";
import type { GlbParse } from "./glb";
import type { MeshBudget } from "./spec";

const PerObjZ = z.object({
  name: z.string(), tris: z.number(), nonmanifold_edges: z.number(), shells: z.number(), uv: z.boolean(), uv_out_of_bounds: z.number(),
  degenerate_faces: z.number(), loose_verts: z.number(), materials: z.number(), bbox_m: z.array(z.number()).length(3),
});
const StatsZ = z.object({
  objects: z.number(), tris: z.number(), nonmanifold_edges: z.number(), uv_objs: z.number(), shells: z.number(), degenerate_faces: z.number(),
  materials: z.number(), bbox_m: z.array(z.number()).length(3), per_obj: z.array(PerObjZ).max(256),
});
/** The harness output. Parsed defensively: it was written by a process that ran untrusted input. */
export const HarnessResultZ = z.object({
  v: z.literal(1),
  harness: z.number(),
  ok: z.boolean(),
  blender: z.string().max(80),
  name: z.string().max(64).optional(),
  rung: z.string().max(16).nullable().optional(),
  timings: z.record(z.string(), z.number()).default({}),
  error: z.object({ stage: z.string().max(32), type: z.string().max(32), message: z.string().max(800) }).optional(),
  guard: z.array(z.object({ line: z.number(), code: z.string(), message: z.string() })).max(50).optional(),
  stats: StatsZ.optional(),
  decimated: z.object({ from: z.number(), to: z.number(), ratio: z.number(), s: z.number() }).nullable().optional(),
