// Cyrus meshgen WORKER (workerClass linux-cpu, job type "meshgen"): submit side + pull-based claim loop.
// The box is reached ONLY through the JobQueue + ObjectStore interfaces (lib/cyrus/jobs/asset-jobs.ts) and an
// injected BlenderRunner (./runner.ts). OFF unless CYRUS_MESHGEN=1 (submit refuses, the loop returns at once);
// rung 3 additionally needs CYRUS_MESHGEN_SCRATCH=1. No model is called here: the spec/script arrives in the request
// (the build service called the model and passes its token usage along for the record).
// Fail closed: a mesh with any error-severity issue is not stored (no glb, no manifest); only its record + renders.
import { isTrue } from "../host/types";
import { sha256Hex, type AssetJob, type JobQueue, type ObjectStore } from "../jobs/asset-jobs";
import { checkMesh, hasErrors, HarnessResultZ, type MeshIssue } from "./checks";
import { parseGlb } from "./glb";
import { buildManifest, moduleOf, RECORD_KIND, GENERATOR, type MeshgenRecord, type MeshgenVerdict } from "./output";
import type { BlenderRun, BlenderRunner } from "./runner";
import { scanScratchScript } from "./scan";
import { MeshgenRequestZ, zodIssues, type MeshgenRequest, type MeshgenRequestInput, type SpecIssue } from "./spec";
import { checkSpec } from "./templates";

export const MESHGEN_JOB_TYPE = "meshgen";
export const MESHGEN_FLAG = "CYRUS_MESHGEN";
export const MESHGEN_SCRATCH_FLAG = "CYRUS_MESHGEN_SCRATCH";
/** Default job budgets (lock wait + Blender + transfer). A rung-1 round took ~11-14 s of Blender in the flights. */
export const MESHGEN_TIMEOUT_MS = { template: 8 * 60_000, kit: 8 * 60_000, scratch: 12 * 60_000 } as const;
/** Safety margin kept back from the job's timeout so the worker can still record + complete before the sweep. */
const MARGIN_MS = 15_000;

type Env = Record<string, string | undefined>;
export const meshgenEnabled = (env: Env = process.env) => isTrue(env[MESHGEN_FLAG]);
export const scratchEnabled = (env: Env = process.env) => meshgenEnabled(env) && isTrue(env[MESHGEN_SCRATCH_FLAG]);

const enc = (o: unknown) => new TextEncoder().encode(JSON.stringify(o));

export type SubmitResult =
  | { ok: true; job: AssetJob; requestKey: string; request: MeshgenRequest }
  | { ok: false; code: "switched_off" | "scratch_off" | "invalid"; issues: SpecIssue[] };

/** Validate everything that can be validated before any compute is spent, store the request, enqueue the job. */
export async function submitMeshgen(input: MeshgenRequestInput, deps: { queue: JobQueue; store: ObjectStore; env?: Env; timeoutMs?: number }): Promise<SubmitResult> {
  const env = deps.env ?? process.env;
  if (!meshgenEnabled(env)) return { ok: false, code: "switched_off", issues: [{ path: "", code: "switched_off", message: "AI mesh is switched off (CYRUS_MESHGEN)" }] };
  const r = MeshgenRequestZ.safeParse(input);
  if (!r.success) return { ok: false, code: "invalid", issues: zodIssues(r.error, "request") };
  let req = r.data;
  if (req.rung === "template" || req.rung === "kit") {
    const c = checkSpec(req.rung, req.rung === "template" ? req.template : null, req.spec);
    if (!c.ok) return { ok: false, code: "invalid", issues: c.issues };
    req = { ...req, spec: c.spec };
  } else {
    if (!scratchEnabled(env)) return { ok: false, code: "scratch_off", issues: [{ path: "rung", code: "scratch_off", message: "from-scratch scripts are switched off (CYRUS_MESHGEN_SCRATCH)" }] };
    const s = scanScratchScript(req.script);
    if (s.length) return { ok: false, code: "invalid", issues: s.slice(0, 20).map((i) => ({ path: `script:${i.line}`, code: `scan_${i.code}`, message: i.message })) };
  }
  const requestKey = await deps.store.put(enc(req));
  const job = await deps.queue.enqueue({ type: MESHGEN_JOB_TYPE, workerClass: "linux-cpu", projectId: req.projectId, inputs: [requestKey], timeoutMs: deps.timeoutMs ?? MESHGEN_TIMEOUT_MS[req.rung] });
  return { ok: true, job, requestKey, request: req };
}

/** The request.json the Blender harness reads. */
export function harnessRequestFor(req: MeshgenRequest): Record<string, unknown> {
  const common = { v: 1, name: req.assetId, rung: req.rung, budget: { maxTriangles: req.budget.maxTriangles, decimate: req.budget.decimate }, render: req.render ? { samples: req.render.samples } : null };
  if (req.rung === "template") return { ...common, template: req.template, spec: req.spec };
  if (req.rung === "kit") return { ...common, kit: req.kit, spec: req.spec };
  return { ...common, script: "scratch.py" };
}

export type WorkerDeps = {
  queue: JobQueue;
  store: ObjectStore;
  runner: BlenderRunner;
  workerId: string;
  env?: Env;
  now?: () => number;
  /** Called with every record written (logging, tests, the flights script). */
  onRecord?: (rec: MeshgenRecord, run: BlenderRun | null) => void;
};

function baseRecord(job: AssetJob, req: MeshgenRequest, deps: WorkerDeps): MeshgenRecord {
  const mod = moduleOf(req);
  return {
    schema: 1, kind: RECORD_KIND, jobId: job.id, requestKey: job.inputs[0], assetId: req.assetId, projectId: req.projectId, game: req.game, category: req.category,
    rung: req.rung, module: mod.module, moduleVersion: mod.version, verdict: "not_run", issues: [], stats: null, decimated: null,
    outputs: { glb: null, manifest: null, sheet: null, renders: [] },
    tokens: { estimate: req.estimate ?? null, usage: req.usage ?? null },
    compute: { wallMs: 0, lockWaitMs: 0, blenderSeconds: null, exitCode: null, worker: deps.workerId },
    engine: { blender: null, harness: null, filesSha256: "", runner: deps.runner.id },
    provenance: { generator: GENERATOR, legalClass: "ai-generated-for-user", source: "ai" },
    at: new Date((deps.now ?? Date.now)()).toISOString(),
  };
}

export type ProcessOutcome = { record: MeshgenRecord | null; completed: boolean; failed: string | null };

/** Run one claimed meshgen job end to end. Never throws for job-level problems (they are recorded or the job fails). */
export async function processMeshgenJob(job: AssetJob, deps: WorkerDeps): Promise<ProcessOutcome> {
  const now = deps.now ?? Date.now;
  const failJob = async (msg: string): Promise<ProcessOutcome> => { await deps.queue.fail(job.id, deps.workerId, msg); return { record: null, completed: false, failed: msg }; };
  if (job.type !== MESHGEN_JOB_TYPE) return failJob(`not a meshgen job (${job.type})`);
  const raw = job.inputs[0] ? await deps.store.get(job.inputs[0]) : null;
  if (!raw) return failJob("request object missing from the store");
  let parsed: unknown;
  try { parsed = JSON.parse(new TextDecoder().decode(raw)); } catch { return failJob("request object is not JSON"); }
  const pr = MeshgenRequestZ.safeParse(parsed);
  if (!pr.success) return failJob(`invalid request: ${zodIssues(pr.error)[0]?.message ?? "?"}`);
  const req = pr.data;
  if (req.rung === "scratch" && !scratchEnabled(deps.env ?? process.env)) return failJob("from-scratch scripts are switched off (CYRUS_MESHGEN_SCRATCH)");
  const rec = baseRecord(job, req, deps);
  const remaining = job.timeoutMs - (now() - (job.claimedAt ?? now())) - MARGIN_MS;
  if (remaining < 30_000) return failJob("not enough of the job's time budget left to run");

  let run: BlenderRun | null = null;
  try {
    run = await deps.runner.run({ jobId: job.id, harnessRequest: harnessRequestFor(req), scratchScript: req.rung === "scratch" ? req.script : undefined, timeoutMs: remaining });
  } catch (e) {
    run = null; rec.verdict = "not_run"; rec.notRunReason = `runner error: ${(e as Error).message.slice(0, 200)}`;
  }
  if (run) {
    rec.compute = { wallMs: run.wallMs, lockWaitMs: run.lockWaitMs, blenderSeconds: null, exitCode: run.exitCode, worker: deps.workerId };
    rec.engine.filesSha256 = run.filesSha256;
    // renders are kept even for a rejected mesh: the model looks at them in the next round
    for (const [name, data] of [...run.files].sort(([a], [b]) => a.localeCompare(b))) {
      if (!name.endsWith(".png")) continue;
      const key = await deps.store.put(data);
      if (name.endsWith("_sheet.png")) rec.outputs.sheet = key; else rec.outputs.renders.push(key);
    }
  }
  let verdict: MeshgenVerdict = rec.verdict;
  if (run && (run.status === "busy" || run.status === "transport")) { verdict = "not_run"; rec.notRunReason = run.error ?? run.status; }
  else if (run && (run.status === "timeout" || run.status === "crashed")) {
    verdict = "rejected";
    rec.issues = [{ code: run.status === "timeout" ? "timeout" : "crashed", severity: "error", path: "run", message: run.error ?? run.status }];
  } else if (run) {
    const hr = HarnessResultZ.safeParse(run.result);
    if (!hr.success) { verdict = "rejected"; rec.issues = [{ code: "bad_harness_result", severity: "error", path: "harness", message: hr.error.issues[0]?.message ?? "unreadable" }]; }
    else {
      const result = hr.data;
      rec.engine.blender = result.blender; rec.engine.harness = result.harness; rec.compute.blenderSeconds = result.timings.total_s ?? null;
      rec.stats = result.stats ?? null; rec.decimated = result.decimated ? { from: result.decimated.from, to: result.decimated.to, ratio: result.decimated.ratio } : null;
      const glbBytes = result.glb ? run.files.get(result.glb.file) ?? null : null;
      const glb = glbBytes ? parseGlb(glbBytes) : null;
      const issues: MeshIssue[] = checkMesh({ result, glb, budget: req.budget });
      if (!hasErrors(issues) && glbBytes) {
        const m = buildManifest(req, sha256Hex(glbBytes));
        if (!m.ok) issues.push(...m.errors.map((e) => ({ code: `manifest_${e.code}`, severity: "error" as const, path: e.path, message: e.message })));
        else {
          rec.outputs.glb = await deps.store.put(glbBytes);
          rec.outputs.manifest = await deps.store.put(enc(m.manifest));
        }
      }
      rec.issues = issues;
      verdict = hasErrors(issues) ? "rejected" : "accepted";
    }
  }
  rec.verdict = verdict;
  const recordKey = await deps.store.put(enc(rec));
  deps.onRecord?.(rec, run);
  if (verdict === "not_run") {
    // the build host never ran it: fail the job (the caller may resubmit); the record explains why
    await deps.queue.fail(job.id, deps.workerId, `not_run: ${rec.notRunReason ?? "?"} record=${recordKey}`);
    return { record: rec, completed: false, failed: rec.notRunReason ?? "not_run" };
  }
  // outputs[0] is ALWAYS the record; consumers read record.verdict (done = the worker finished, not "accepted")
  const outputs = [recordKey, rec.outputs.glb, rec.outputs.manifest, rec.outputs.sheet, ...rec.outputs.renders].filter((k): k is string => !!k);
  const done = await deps.queue.complete(job.id, deps.workerId, outputs);
  // null = the sweep expired the job meanwhile; the record stays in the store but the job is not marked done
  return { record: rec, completed: !!done, failed: done ? null : "job expired before completion" };
}

export type LoopResult = { processed: number; accepted: number; rejected: number; notRun: number; expired: number; skipped: string | null };

/** Pull loop: sweep, claim one meshgen job, run it; repeat until maxJobs, idle timeout or abort. One job at a time. */
export async function runMeshgenWorker(deps: WorkerDeps, opts: { maxJobs?: number; idleMs?: number; pollMs?: number; signal?: AbortSignal; sleep?: (ms: number) => Promise<void> } = {}): Promise<LoopResult> {
  const res: LoopResult = { processed: 0, accepted: 0, rejected: 0, notRun: 0, expired: 0, skipped: null };
  if (!meshgenEnabled(deps.env ?? process.env)) return { ...res, skipped: "switched off" };
  const now = deps.now ?? Date.now;
  const sleep = opts.sleep ?? ((ms: number) => new Promise<void>((r) => setTimeout(r, ms)));
  const idleMs = opts.idleMs ?? 0, pollMs = opts.pollMs ?? 2000;
  let idleSince = now();
  while (!opts.signal?.aborted && res.processed < (opts.maxJobs ?? Infinity)) {
    res.expired += (await deps.queue.sweep()).length;
    const job = await deps.queue.claim({ id: deps.workerId, classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] });
    if (!job) {
      if (now() - idleSince >= idleMs) break;
      await sleep(pollMs);
      continue;
    }
    const o = await processMeshgenJob(job, deps);
    res.processed++;
    const v = o.record?.verdict;
    if (v === "accepted") res.accepted++; else if (v === "rejected") res.rejected++; else res.notRun++;
    idleSince = now();
  }
  return res;
}

