// Cyrus meshgen: the MODEL-FACING contract the build service would use (DESIGN + TYPES; not wired into the live build
// service). Flow per asset:
//   1. service: routeMesh(prompt) -> rung + estimate; show the estimate, get the user's go (and the plan gate).
//   2. service -> model: system = meshgenSystemPrompt(rung, template) (cacheable), user = prompt; ONE tool allowed,
//      forced with tool_choice, max_tokens = TOKEN_PROFILES[rung].maxOutputPerRound.
//   3. model -> tool call (JSON spec / kit parts / script). service: submitMeshgen(...) with the call's usage.
//   4. worker runs it; service turns the record into toolResultFor(record) + the contact sheet as an image block.
//   5. model revises (same tool) or answers "done"; stop at TOKEN_PROFILES[rung].maxRounds or when accepted and the
//      model says done. A rejected final round is reported to the user with its issues, never silently "made".
// Pure + client-safe.
import { z } from "zod";
import type { MeshIssue } from "./checks";
import { TOKEN_PROFILES } from "./cost";
import type { MeshgenRecord } from "./output";
import { ScratchSubmissionZ, type Rung } from "./spec";
import { getTemplate, KIT, TEMPLATES } from "./templates";

export const MESH_TOOL_NAMES = { template: "mesh_template", kit: "mesh_kit", scratch: "mesh_script" } as const;
export type MeshToolName = (typeof MESH_TOOL_NAMES)[keyof typeof MESH_TOOL_NAMES];

/** Anthropic-style tool definition (name, description, JSON Schema input). */
export type ToolDef = { name: MeshToolName; description: string; input_schema: Record<string, unknown> };

/** The single tool offered for a rung. The template tool's `spec` schema is that template's own (strict). */
export function meshToolFor(rung: Exclude<Rung, "catalog">, templateId?: string): ToolDef {
  if (rung === "template") {
    const t = getTemplate(templateId ?? "");
    if (!t) throw new Error(`unknown template ${String(templateId)}`);
    return {
      name: MESH_TOOL_NAMES.template,
      description: `Build a ${t.label} from a JSON spec. Only the spec is yours; the mesh is made by fixed code. Revise the spec after looking at the renders.`,
      input_schema: z.toJSONSchema(z.strictObject({ template: z.literal(t.id), spec: t.schema }), { io: "input", unrepresentable: "any" }) as Record<string, unknown>,
    };
  }
  if (rung === "kit") {
    return {
      name: MESH_TOOL_NAMES.kit,
      description: "Assemble a hard-surface prop from kit parts (JSON only). Use groups for the logical parts (lid, body, handle).",
      input_schema: z.toJSONSchema(KIT.schema, { io: "input", unrepresentable: "any" }) as Record<string, unknown>,
    };
  }
  return {
    name: MESH_TOOL_NAMES.scratch,
    description: "Write a Blender Python script defining build(K). Only bmesh, bpy.data, math, mathutils, random. No bpy.ops, files, imports or I/O. K.part(name) returns a Part with box/cyl/sphere/tube/rod/prism/loft; set K.palette for the 7 kit slots.",
    input_schema: z.toJSONSchema(ScratchSubmissionZ, { io: "input" }) as Record<string, unknown>,
  };
}

/** The cacheable system prompt for a rung: rules + the template/kit card. */
export function meshgenSystemPrompt(rung: Exclude<Rung, "catalog">, templateId?: string): string {
  const rules = [
    "You design one game prop for Cyrus. Call the one tool you are given; never write prose instead of the tool call.",
    "Metres, real-world scale. Stylised hard-surface; no logos, no brand names, no text.",
    "After each build you get statistics, issues and a contact sheet. Fix errors first, then proportions, then palette (a near-black or plain white body hides detail).",
    `Stop when the issues list has no errors and the sheet matches the request. You have at most ${TOKEN_PROFILES[rung].maxRounds} builds.`,
  ];
  const card = rung === "template" ? getTemplate(templateId ?? "")?.card ?? "" : rung === "kit" ? KIT.card : "Script rung: see the tool description. Keep it under 300 lines.";
  return `${rules.join("\n")}\n\n${card}`;
}

export type MeshToolResult = {
  status: "accepted" | "rejected" | "not_run";
  round: number;
  roundsLeft: number;
  /** Errors first, at most 12. The model must fix every error. */
  issues: Pick<MeshIssue, "code" | "severity" | "path" | "message">[];
  stats: { triangles: number; budget: number; objects: number; materials: number; extentM: number[]; decimated: boolean } | null;
  /** The contact sheet goes next to this JSON as an image block (object-store key here for the service). */
  sheetKey: string | null;
  next: "revise" | "stop" | "retry_later";
};

const SEV_RANK = { error: 0, warning: 1, info: 2 } as const;

export function toolResultFor(rec: MeshgenRecord, round: number, budgetTriangles: number): MeshToolResult {
  const max = TOKEN_PROFILES[rec.rung].maxRounds;
  const issues = [...rec.issues].sort((a, b) => SEV_RANK[a.severity] - SEV_RANK[b.severity]).slice(0, 12).map(({ code, severity, path, message }) => ({ code, severity, path, message }));
  const roundsLeft = Math.max(0, max - round);
  return {
    status: rec.verdict, round, roundsLeft, issues,
    stats: rec.stats ? { triangles: rec.stats.tris, budget: budgetTriangles, objects: rec.stats.objects, materials: rec.stats.materials, extentM: rec.stats.bbox_m, decimated: !!rec.decimated } : null,
    sheetKey: rec.outputs.sheet,
    next: rec.verdict === "not_run" ? "retry_later" : roundsLeft === 0 ? "stop" : "revise",
  };
}

/** The port the build service would implement around meshgen (types only). */
export interface MeshgenServicePort {
  route(input: { prompt: string; game: string; category?: string; userId: string }): Promise<unknown>;
  submit(input: { assetId: string; projectId: string; tool: MeshToolName; toolInput: unknown; round: number; usage: { inputTokens: number; outputTokens: number; cachedInputTokens: number } }): Promise<{ jobId: string } | { error: string }>;
  poll(jobId: string): Promise<MeshgenRecord | null>;
}

/** Every template's tool, for docs and the admin catalogue. */
export const ALL_TEMPLATE_TOOLS = (): ToolDef[] => TEMPLATES.map((t) => meshToolFor("template", t.id));

