describe("meshgen specs + templates", () => {
  it("every template example and the kit selftest parse", () => {
    for (const t of TEMPLATES) assert.ok(checkSpec("template", t.id, t.example).ok, t.id);
    const kit = JSON.parse(readFileSync(path.join(FIX, "flights.json"), "utf8")).flights.find((f: { id: string }) => f.id === "kit_terminal").spec;
