  it("rejects bad enums, unknown keys and out-of-range numbers with paths", () => {
    const r = checkSpec("template", "rifle", { magazine: { style: "belt" }, laser: true, barrel: { length: 9 } });
    assert.ok(!r.ok);
    const paths = r.issues.map((i) => i.path);
