    assert.ok(r.issues.some((i) => /laser/.test(i.message) || i.path === "spec"), "unknown key reported");
    assert.equal((checkSpec("template", "nope", {}) as { ok: false; issues: { code: string }[] }).issues[0].code, "unknown_template");
  });
  it("kit: required fields per shape, tube radii, mirror letters, primitive cap", () => {
    const bad = checkSpec("kit", null, { parts: [{ shape: "cylinder", radius: 0.1 }, { shape: "tube", radius: 0.1, inner: 0.2, length: 0.1 }, { shape: "box", size: [1, 1, 1], mirror: "xx" }] });
    assert.ok(!bad.ok);
