      assert.match(src, /^SELFTEST = \[/m, `${t.id} has a SELFTEST matrix`);
    }
    const kitSrc = py("mg_kit.py");
    assert.deepEqual(slotsOf(kitSrc), (z2json(KIT.schema) as { properties: { palette: { properties: Record<string, unknown> } } }).properties.palette.properties && slotsOf(kitSrc));
    for (const v of enumValues(z2json(KIT.schema))) assert.ok(kitSrc.includes(`'${v}'`), `kit enum ${v}`);
