import { z } from "zod";
function z2json(s: z.ZodType) { return z.toJSONSchema(s, { io: "input", unrepresentable: "any" }); }
function enumValues(j: unknown, out = new Set<string>()): Set<string> {
  if (j && typeof j === "object") {
    const o = j as Record<string, unknown>;
    if (Array.isArray(o.enum)) for (const v of o.enum) if (typeof v === "string") out.add(v);
    for (const v of Object.values(o)) enumValues(v, out);
  }
  return out;
}

describe("meshgen cost model", () => {
  it("template and scratch estimates sit inside the measured PoC ranges", () => {
    for (const r of ["template", "scratch"] as const) {
      const e = estimateCost(r), [lo, hi] = TOKEN_PROFILES[r].measuredTotal!;
      assert.ok(e.expected.totalTokens >= lo && e.expected.totalTokens <= hi, `${r}: ${e.expected.totalTokens} not in ${lo}-${hi}`);
      assert.equal(e.basis, "measured");
    }
    assert.equal(estimateCost("kit").basis, "assumed");
    const order = (["catalog", "template", "kit", "scratch"] as const).map((r) => estimateCost(r).expected.totalTokens);
    assert.deepEqual([...order].sort((a, b) => a - b), order, "the ladder is cheapest first");
