// ---------------------------------------------------------------- worker + queue
type FakeOpts = { status?: BlenderRun["status"]; result?: unknown; glb?: Uint8Array | null; throws?: boolean; onRun?: () => void };
function fakeRunner(o: FakeOpts = {}): BlenderRunner & { calls: number; last: unknown } {
  const r = {
    id: "fake", calls: 0, last: null as unknown,
    async run(job: Parameters<BlenderRunner["run"]>[0]): Promise<BlenderRun> {
      r.calls++; r.last = job; o.onRun?.();
      if (o.throws) throw new Error("ssh exploded");
      const name = String(job.harnessRequest.name);
      const files = new Map<string, Uint8Array>([[`${name}_v0.png`, new Uint8Array([1, 2, 3])], [`${name}_sheet.png`, new Uint8Array([4, 5])]]);
      if (o.glb !== null) files.set(`${name}.glb`, o.glb ?? tinyGlb({ triangles: 4 }));
      return { status: o.status ?? "ok", exitCode: 0, result: o.result ?? fakeResult({ tris: 4, name }), files, logTail: "", wallMs: 1200, lockWaitMs: 5, totalMs: 1300, filesSha256: "f".repeat(64), runner: "fake" };
    },
  };
  return r;
}

