    assert.equal(rec.verdict, "accepted"); assert.equal(rec.rung, "template"); assert.equal(rec.module, "crate");
    assert.equal(rec.tokens.usage!.outputTokens, 900); assert.equal(rec.tokens.estimate!.totalTokens, 5700);
    assert.ok(rec.outputs.glb && rec.outputs.manifest && rec.outputs.sheet && rec.outputs.renders.length === 1);
    const man = JSON.parse(new TextDecoder().decode((await store.get(rec.outputs.manifest!))!));
    assert.equal(man.geometry.sha256, rec.outputs.glb!.slice(7), "manifest points at the stored glb bytes");
    assert.deepEqual(job.outputs, [job.outputs[0], rec.outputs.glb, rec.outputs.manifest, rec.outputs.sheet, ...rec.outputs.renders]);
  });
  it("rejected (non-manifold): no glb, no manifest, renders kept for the next round", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    const s = await submitMeshgen(req(), { queue, store, env: ON }); assert.ok(s.ok);
    const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
    const o = await processMeshgenJob(job, { queue, store, runner: fakeRunner({ result: fakeResult({ tris: 4, nonmanifold: 2, name: "crate_a" }) }), workerId: "w", env: ON });
    assert.equal(o.record!.verdict, "rejected"); assert.equal(o.record!.outputs.glb, null); assert.equal(o.record!.outputs.manifest, null);
    assert.ok(o.record!.outputs.sheet); assert.equal((await queue.get(job.id))!.status, "done");
    assert.ok(!(await store.has(`sha256/${sha256Hex(tinyGlb({ triangles: 4 }))}`)), "the rejected glb never entered the store");
  });
  it("busy / transport / runner throw -> not_run and the job fails; timeout -> rejected", async () => {
    for (const [o, verdict, status] of [[{ status: "busy" }, "not_run", "failed"], [{ throws: true }, "not_run", "failed"], [{ status: "timeout" }, "rejected", "done"], [{ status: "crashed" }, "rejected", "done"]] as const) {
      const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
      const s = await submitMeshgen(req(), { queue, store, env: ON }); assert.ok(s.ok);
      const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
      const out = await processMeshgenJob(job, { queue, store, runner: fakeRunner(o as FakeOpts), workerId: "w", env: ON });
      assert.equal(out.record!.verdict, verdict, JSON.stringify(o)); assert.equal((await queue.get(job.id))!.status, status);
    }
  });
  it("a job the sweep expired while Blender ran is not completed (the record stays)", async () => {
    let t = 0;
    const queue = createMemoryJobQueue(() => t), store = createMemoryObjectStore();
    const s = await submitMeshgen(req(), { queue, store, env: ON, timeoutMs: 60_000 }); assert.ok(s.ok);
    const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
    const runner = fakeRunner({ onRun: () => { t = 61_000; void queue.sweep(); } });
    const out = await processMeshgenJob(job, { queue, store, runner, workerId: "w", env: ON, now: () => t });
    assert.equal(out.completed, false); assert.equal((await queue.get(job.id))!.status, "expired"); assert.equal(out.record!.verdict, "accepted");
  });
  it("loop: switched off returns at once; idles out; scratch job refused when the scratch flag is off at run time", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    assert.equal((await runMeshgenWorker({ queue, store, runner: fakeRunner(), workerId: "w", env: {} })).skipped, "switched off");
    const r = await runMeshgenWorker({ queue, store, runner: fakeRunner(), workerId: "w", env: ON }, { idleMs: 0 });
    assert.equal(r.processed, 0);
    const lantern = readFileSync(path.join(FIX, "scratch-lantern.py"), "utf8");
    const s = await submitMeshgen(req({ rung: "scratch", script: lantern, category: "prop" } as never), { queue, store, env: ON3 }); assert.ok(s.ok);
    const runner = fakeRunner();
    await runMeshgenWorker({ queue, store, runner, workerId: "w", env: ON }, { maxJobs: 1 });
    assert.equal(runner.calls, 0); assert.equal((await queue.get(s.job.id))!.status, "failed");
  });
});

// ---------------------------------------------------------------- node-2 runner (fake transport)
function fakeRemote(reply: (cmd: string, input?: Buffer) => { code: number; stdout: string; stderr?: string }): Remote & { cmds: string[] } {
  const cmds: string[] = [];
  return { cmds, exec: async (c, o) => { cmds.push(c); const r = reply(c, o?.input); return { code: r.code, stdout: r.stdout, stderr: r.stderr ?? "" }; } };
}
const outTar = (files: Record<string, string | Uint8Array>) => tarball(Object.entries(files).map(([name, d]) => ({ name, data: Buffer.from(d as never) }))).toString("base64");

describe("meshgen node-2 runner", () => {
  it("ships harness + request in one tar, runs the sandbox script, reads regular files back", async () => {
    let shipped: Map<string, Uint8Array> | null = null;
    const remote = fakeRemote((_c, input) => {
      shipped = untar(input!);
      return { code: 0, stdout: outTar({ "meta/exit": "0\n", "meta/wall_ms": "11000", "meta/lock_wait_ms": "3", "meta/log.txt": "Blender 5.2.2", "work/result.json": JSON.stringify(fakeResult({ name: "x" })), "work/x.glb": tinyGlb() }) };
    });
    const runner = createNode2BlenderRunner({ remote });
    const r = await runner.run({ jobId: "job_7", harnessRequest: { v: 1, name: "x" }, timeoutMs: 300_000 });
    assert.equal(r.status, "ok"); assert.equal(r.wallMs, 11000); assert.ok(r.files.has("x.glb"));
    assert.equal(r.filesSha256, harnessFiles().sha256);
    const names = [...shipped!.keys()].sort();
    assert.ok(names.includes("in/mg_harness.py") && names.includes("in/sbx-meshgen.sh") && names.includes("in/request.json"));
    assert.match(remote.cmds[0], /sbx-meshgen\.sh" "\$J" '\/tank\/nxeon-build\/tmp\/blender-poc\/blender-5\.2\.2-linux-x64' \d+ \d+/);
    assert.match(remote.cmds[0], /\/tank\/nxeon-build\/tmp\/meshgen\/jobs\/mg-job-7-[0-9a-f]{8}/);
  });
  it("maps lock busy, timeout, missing result and transport failures", async () => {
    const run = (stdout: string, code = 0) => createNode2BlenderRunner({ remote: fakeRemote(() => ({ code, stdout, stderr: "boom" })) }).run({ jobId: "j", harnessRequest: {}, timeoutMs: 120_000 });
    assert.equal((await run(outTar({ "meta/exit": "75" }))).status, "busy");
    assert.equal((await run(outTar({ "meta/exit": "124" }))).status, "timeout");
    assert.equal((await run(outTar({ "meta/exit": "137", "meta/log.txt": "Killed" }))).status, "crashed");
    assert.equal((await run("", 0)).status, "transport");
    assert.equal((await run("", 255)).status, "transport");
    assert.equal((await run("not base64 tar!!")).status, "transport");
  });
  it("untar refuses unsafe names and ignores non-regular entries", () => {
    const t = tarball([{ name: "work/a.txt", data: Buffer.from("a") }]);
    assert.equal(Buffer.from(untar(t).get("work/a.txt")!).toString(), "a");
    const link = Buffer.from(t); link[156] = "2".charCodeAt(0); // symlink type flag (checksum ignored by the reader)
    assert.equal(untar(link).size, 0);
  });
});

describe("meshgen model-facing contract", () => {
