// Cyrus meshgen (Model Studio L4, AI mesh): specs, templates, router + cost, scan, glb, checks, manifest, worker loop on
// the in-memory queue, node-2 runner against a fake transport, model-facing contract. Pure, no Blender, no network.
// Run: tsx --test test/cyrus-meshgen.test.ts   (the real Blender suite is test/cyrus-meshgen-blender.test.ts)
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { validateAssetProfile } from "../lib/cyrus/adapters/asset-profile";
import { minecraftAssetProfile } from "../lib/cyrus/adapters/minecraft";
import { libraryEligible } from "../lib/cyrus/assets3d/manifest";
import { createMemoryJobQueue, createMemoryObjectStore, sha256Hex } from "../lib/cyrus/jobs/asset-jobs";
import { tarball, type Remote } from "../lib/cyrus/testflight/client";
import {
  checkSpec, createFakeCatalog, estimateCost, parsePrices, PRICE_SETTING_KEYS, routeMesh, TEMPLATES, KIT, pythonFilesFor, extractJsonObject,
  scanScratchScript, ALLOWED_IMPORTS, DENY_NAMES, DENY_ATTRS, parseGlb, checkMesh, hasErrors, buildManifest, resolveBudget, DRAFT_MESH_PROFILE,
  meshToolFor, toolResultFor, meshgenSystemPrompt, MeshgenRequestZ, TOKEN_PROFILES, dollarsFor, type MeshgenRecord, type MeshgenRequestInput,
} from "../lib/cyrus/meshgen";
import { BLENDER_SOURCE_DIR, createNode2BlenderRunner, harnessFiles, untar, type BlenderRun, type BlenderRunner } from "../lib/cyrus/meshgen/runner";
import { MESHGEN_JOB_TYPE, processMeshgenJob, runMeshgenWorker, submitMeshgen, harnessRequestFor } from "../lib/cyrus/meshgen/worker";
import { fakeResult, tinyGlb } from "./_cyrus-meshgen-fixtures";

const FIX = path.join(__dirname, "fixtures", "cyrus-meshgen");
const ON = { CYRUS_MESHGEN: "1" } as const;
const ON3 = { CYRUS_MESHGEN: "1", CYRUS_MESHGEN_SCRATCH: "1" } as const;
const py = (f: string) => readFileSync(path.join(BLENDER_SOURCE_DIR, f), "utf8");
const budget = () => { const b = resolveBudget(DRAFT_MESH_PROFILE, "container"); assert.ok(b.ok); return b.budget; };
const req = (o: Partial<MeshgenRequestInput> = {}): MeshgenRequestInput => ({
  v: 1, assetId: "crate_a", projectId: "proj_1", game: "gltf-prop-draft", category: "container", prompt: "sci-fi crate",
  budget: budget(), rung: "template", template: "crate", spec: { style: "scifi" }, ...o,
} as MeshgenRequestInput);

describe("meshgen specs + templates", () => {
  it("every template example and the kit selftest parse", () => {
    for (const t of TEMPLATES) assert.ok(checkSpec("template", t.id, t.example).ok, t.id);
    const kit = JSON.parse(readFileSync(path.join(FIX, "flights.json"), "utf8")).flights.find((f: { id: string }) => f.id === "kit_terminal").spec;
    assert.ok(checkSpec("kit", null, kit).ok);
  });
  it("rejects bad enums, unknown keys and out-of-range numbers with paths", () => {
    const r = checkSpec("template", "rifle", { magazine: { style: "belt" }, laser: true, barrel: { length: 9 } });
    assert.ok(!r.ok);
    const paths = r.issues.map((i) => i.path);
    assert.ok(paths.includes("spec.magazine.style") && paths.includes("spec.barrel.length"), paths.join());
    assert.ok(r.issues.some((i) => /laser/.test(i.message) || i.path === "spec"), "unknown key reported");
    assert.equal((checkSpec("template", "nope", {}) as { ok: false; issues: { code: string }[] }).issues[0].code, "unknown_template");
  });
  it("kit: required fields per shape, tube radii, mirror letters, primitive cap", () => {
    const bad = checkSpec("kit", null, { parts: [{ shape: "cylinder", radius: 0.1 }, { shape: "tube", radius: 0.1, inner: 0.2, length: 0.1 }, { shape: "box", size: [1, 1, 1], mirror: "xx" }] });
    assert.ok(!bad.ok);
    const msgs = bad.issues.map((i) => i.message).join("|");
    assert.match(msgs, /cylinder needs length/); assert.match(msgs, /inner must be smaller/); assert.match(msgs, /mirror/);
    const many = checkSpec("kit", null, { parts: [{ shape: "box", size: [0.1, 0.1, 0.1], array: { count: 64, step: [0.1, 0, 0] }, mirror: "xyz" }, { shape: "box", size: [0.1, 0.1, 0.1], array: { count: 64, step: [0.1, 0, 0] }, mirror: "xy" }] });
    assert.ok(!many.ok && many.issues.some((i) => /primitives after mirror/.test(i.message)));
  });
  it("Python modules exist, declare the same id/version/slots, and implement every enum value the schema allows", () => {
    for (const f of pythonFilesFor()) assert.ok(existsSync(path.join(BLENDER_SOURCE_DIR, f)), f);
    const slotsOf = (src: string) => JSON.parse(/^SLOTS = (\[.*\])$/m.exec(src)![1].replace(/'/g, '"'));
    for (const t of TEMPLATES) {
      const src = py(`${t.module}.py`), all = [src, ...t.deps.map(py)].join("\n");
      assert.equal(/^TEMPLATE_ID = '(\w+)'/m.exec(src)?.[1], t.id);
      assert.equal(Number(/^VERSION = (\d+)/m.exec(src)?.[1]), t.version);
      const js = z2json(t.schema) as { properties: Record<string, unknown> };
      const pal = (js.properties.palette as { properties: Record<string, unknown> }).properties;
      assert.deepEqual(Object.keys(pal).sort(), [...slotsOf(src)].sort(), `${t.id} palette slots`);
      for (const v of enumValues(js)) assert.ok(all.includes(`'${v}'`), `${t.id}: enum value ${v} has no Python implementation`);
      assert.match(src, /^SELFTEST = \[/m, `${t.id} has a SELFTEST matrix`);
    }
    const kitSrc = py("mg_kit.py");
    assert.deepEqual(slotsOf(kitSrc), (z2json(KIT.schema) as { properties: { palette: { properties: Record<string, unknown> } } }).properties.palette.properties && slotsOf(kitSrc));
    for (const v of enumValues(z2json(KIT.schema))) assert.ok(kitSrc.includes(`'${v}'`), `kit enum ${v}`);
  });
  it("extracts one JSON object from a model reply", () => {
    assert.deepEqual(extractJsonObject('here:\n```json\n{"a":1}\n```').ok && (extractJsonObject('```json\n{"a":1}\n```') as { value: unknown }).value, { a: 1 });
    assert.equal(extractJsonObject("no json").ok, false);
    assert.equal(extractJsonObject("{bad").ok, false);
  });
});

import { z } from "zod";
function z2json(s: z.ZodType) { return z.toJSONSchema(s, { io: "input", unrepresentable: "any" }); }
function enumValues(j: unknown, out = new Set<string>()): Set<string> {
  if (j && typeof j === "object") {
    const o = j as Record<string, unknown>;
    if (Array.isArray(o.enum)) for (const v of o.enum) if (typeof v === "string") out.add(v);
    for (const v of Object.values(o)) enumValues(v, out);
  }
  return out;
}

describe("meshgen cost model", () => {
  it("template and scratch estimates sit inside the measured PoC ranges", () => {
    for (const r of ["template", "scratch"] as const) {
      const e = estimateCost(r), [lo, hi] = TOKEN_PROFILES[r].measuredTotal!;
      assert.ok(e.expected.totalTokens >= lo && e.expected.totalTokens <= hi, `${r}: ${e.expected.totalTokens} not in ${lo}-${hi}`);
      assert.equal(e.basis, "measured");
    }
    assert.equal(estimateCost("kit").basis, "assumed");
    const order = (["catalog", "template", "kit", "scratch"] as const).map((r) => estimateCost(r).expected.totalTokens);
    assert.deepEqual([...order].sort((a, b) => a - b), order, "the ladder is cheapest first");
  });
  it("no prices -> dollars null; configured prices -> tokens x price (no invented numbers)", () => {
    const e = estimateCost("template");
    assert.equal(e.dollars, null); assert.ok(e.notes.some((n) => /no token prices/.test(n)));
    assert.equal(parsePrices({}), null);
    assert.equal(parsePrices({ [PRICE_SETTING_KEYS.input]: "x", [PRICE_SETTING_KEYS.output]: "2" }), null);
    const p = parsePrices({ [PRICE_SETTING_KEYS.input]: "1", [PRICE_SETTING_KEYS.output]: "10", [PRICE_SETTING_KEYS.cacheRead]: "0.1" })!;
    assert.equal(dollarsFor({ inputTokens: 1_000_000, cachedInputTokens: 1_000_000, outputTokens: 100_000 }, p), 1 + 0.1 + 1);
    const w = estimateCost("template", { prices: p });
    assert.ok(w.dollars !== null && w.worstCaseDollars! > w.dollars);
  });
});

describe("meshgen router (deterministic cost ladder)", () => {
  const go = (prompt: string, o: Parameters<typeof routeMesh>[0] extends infer T ? Partial<T> : never = {}) => routeMesh({ prompt, game: "gltf-prop-draft", ...o });
  it("picks a template by keyword, the kit for other hard-surface props", async () => {
    const a = await go("AK-style assault rifle with wood furniture");
    assert.ok(a.ok && a.rung === "template" && a.templateId === "rifle");
    assert.ok(a.ok && a.warnings.some((w) => /real weapon/.test(w)) === false); // "AK-style" is a style word, ak47 is the name
    const b = await go("an AK-47");
    assert.ok(b.ok && b.templateId === "rifle" && b.warnings.some((w) => /ak47/.test(w)));
    for (const [p, t] of [["sci-fi supply crate", "crate"], ["wooden loot chest", "crate"], ["a glowing katana", "sword"], ["knight's longsword", "sword"]] as const) {
      const r = await go(p); assert.ok(r.ok && r.templateId === t, `${p} -> ${JSON.stringify(r)}`);
    }
    const k = await go("a camping lantern");
    assert.ok(k.ok && k.rung === "kit" && k.templateId === null);
    const rev = await go("a six-shot revolver");
    assert.ok(rev.ok && rev.rung === "kit", "an excluded word keeps the rifle template away");
    const cat = await go("crate", { category: "weapon-melee" });
    assert.ok(cat.ok && cat.rung === "kit", "category mismatch keeps the crate template away");
  });
  it("refuses characters/creatures, routes organic shapes to scratch only when it is on", async () => {
    const d = await go("a dragon"); assert.ok(!d.ok && d.code === "refused");
    const c = await go("a statue base", { category: "character" }); assert.ok(!c.ok && c.code === "refused");
    const t = await go("an oak tree"); assert.ok(!t.ok && t.code === "unavailable" && /from-scratch/.test(t.reason));
    const t3 = await go("an oak tree", { availability: { scratch: true } });
    assert.ok(t3.ok && t3.rung === "scratch" && t3.warnings.some((w) => /organic/.test(w)));
  });
  it("catalog first when a candidate clears the threshold; estimate attached; forceRung rules", async () => {
    const catalog = createFakeCatalog([{ assetId: "lib_crate_1", title: "Sci-fi supply crate", tags: ["crate", "scifi", "supply"] }, { assetId: "lib_other", title: "Barrel", tags: ["barrel"], games: ["fivem"] }]);
    const r = await go("sci-fi supply crate", { availability: { catalog } });
    assert.ok(r.ok && r.rung === "catalog" && r.candidates[0].assetId === "lib_crate_1");
    assert.ok(r.ok && r.estimate.rung === "catalog");
    const low = await go("big supply crate with glowing panels", { availability: { catalog } });
    assert.ok(low.ok && low.rung === "template", "a weak catalog score falls through to the template");
    const forced = await go("sci-fi crate", { forceRung: "scratch" });
    assert.ok(!forced.ok && forced.code === "unavailable");
    const forced3 = await go("sci-fi crate", { forceRung: "scratch", availability: { scratch: true } });
    assert.ok(forced3.ok && forced3.rung === "scratch" && forced3.estimate.basis === "measured");
    const cheaper = await go("a camping lantern", { forceRung: "template" });
    assert.ok(!cheaper.ok && cheaper.code === "unavailable");
    const r1 = await go("sci-fi crate"), r2 = await go("sci-fi crate");
    assert.deepEqual(r1, r2, "deterministic");
    const bad = await go("  "); assert.ok(!bad.ok && bad.code === "bad_request");
  });
});

describe("meshgen budgets", () => {
  it("draft profile is a valid AssetProfile; per-category narrowing; games without a budget fail closed", () => {
    assert.deepEqual(validateAssetProfile(DRAFT_MESH_PROFILE), []);
    const c = resolveBudget(DRAFT_MESH_PROFILE, "container"); assert.ok(c.ok && c.budget.maxTriangles === 8000 && c.budget.maxExtentM === 4);
    const w = resolveBudget(DRAFT_MESH_PROFILE, "weapon-ranged"); assert.ok(w.ok && w.budget.maxTriangles === 10000);
    const mc = resolveBudget(minecraftAssetProfile, "prop"); assert.ok(!mc.ok && /no mesh budget/.test(mc.reason));
