    assert.ok(codes.includes("bad_lods"));
  });
});

describe("meshgen scratch scan (rung 3, not the security boundary)", () => {
  it("TS deny lists equal the in-sandbox Python guard's", () => {
    const src = py("mg_scratch.py");
    const set = (name: string) => [...new Set([...new RegExp(`^${name} = \\{([^}]*)\\}`, "ms").exec(src)![1].matchAll(/'([^']+)'/g)].map((m) => m[1]))].sort();
    assert.deepEqual(set("ALLOWED_IMPORTS"), [...ALLOWED_IMPORTS].sort());
    assert.deepEqual(set("DENY_NAMES"), [...DENY_NAMES].sort());
