  });
  it("passes the lantern fixture, rejects the hostile one on every rule it breaks", () => {
    assert.deepEqual(scanScratchScript(readFileSync(path.join(FIX, "scratch-lantern.py"), "utf8")), []);
    const codes = new Set(scanScratchScript(readFileSync(path.join(FIX, "scratch-escape.py"), "utf8")).map((i) => i.code));
    for (const c of ["import_denied", "name_denied", "bpy_ops", "attr_denied", "dunder_string"]) assert.ok(codes.has(c), c);
  });
  it("aliasing, private attrs, globals, from-imports, missing build, size caps", () => {
    const has = (s: string, c: string) => scanScratchScript(`def build(K):\n    pass\n${s}\n`).some((i) => i.code === c);
