    assert.ok(has("K.__class__", "private_attr"));
    assert.ok(has("y = K._secret", "private_attr"));
    assert.ok(has("global q", "global_denied"));
    assert.ok(has("from os import path", "import_denied"));
    assert.ok(has("from math import *", "import_denied"));
    assert.ok(has("bpy.data.texts.new('a')", "attr_denied"));
    assert.ok(!has("import bmesh\nbm = bmesh.new(); bmesh.ops.create_cube(bm)", "bpy_ops"), "bmesh.ops is allowed");
    assert.ok(!has("s = 'a # not a comment'", "name_denied"));
    assert.ok(scanScratchScript("x = 1\n").some((i) => i.code === "no_build"));
    assert.ok(scanScratchScript("def build(K):\n" + "    x = 1\n".repeat(700)).some((i) => i.code === "too_many_lines"));
  });
});

describe("meshgen glb + checks", () => {
  it("parses a valid GLB and counts triangles; flags broken containers", () => {
    const g = parseGlb(tinyGlb({ triangles: 4, materials: 2 }));
    assert.ok(g.ok, JSON.stringify(g.issues)); assert.equal(g.info!.triangles, 4); assert.equal(g.info!.materials, 2);
    assert.equal(parseGlb(tinyGlb().subarray(0, 30)).issues[0].code, "glb_length");
    assert.equal(parseGlb(new Uint8Array(40)).issues[0].code, "glb_magic");
    const ext = parseGlb(tinyGlb({ extraJson: { buffers: [{ byteLength: 36, uri: "data:application/octet-stream;base64,AA==" }] } }));
    assert.ok(ext.issues.some((i) => i.code === "gltf_external_uri"));
    const lines = parseGlb(tinyGlb({ extraJson: { meshes: [{ primitives: [{ attributes: { POSITION: 0 }, mode: 1 }] }] } }));
    assert.ok(lines.issues.some((i) => i.code === "gltf_primitive_mode"));
    const req = parseGlb(tinyGlb({ extraJson: { extensionsRequired: ["KHR_draco_mesh_compression"] } }));
    assert.ok(req.issues.some((i) => i.code === "gltf_extension_required"));
  });
  it("clean build passes; each failure is a structured error", () => {
    const b = budget();
    const ok = checkMesh({ result: fakeResult({ tris: 4 }), glb: parseGlb(tinyGlb({ triangles: 4 })), budget: b });
    assert.ok(!hasErrors(ok), JSON.stringify(ok));
    const codes = (r: ReturnType<typeof fakeResult>, glbTris = r.stats!.tris) => checkMesh({ result: r, glb: parseGlb(tinyGlb({ triangles: glbTris })), budget: b }).filter((i) => i.severity === "error").map((i) => i.code);
    assert.deepEqual(codes(fakeResult({ tris: 4, nonmanifold: 3 })), ["non_manifold"]);
    assert.deepEqual(codes(fakeResult({ tris: 9000 })), ["over_budget_triangles"]);
    assert.deepEqual(codes(fakeResult({ tris: 4, uv: false })), ["missing_uv"]);
    assert.deepEqual(codes(fakeResult({ tris: 4, materials: 9 })), ["too_many_materials"]);
    assert.deepEqual(codes(fakeResult({ tris: 4, reimport: 5 })), ["glb_reimport_mismatch"]);
    assert.deepEqual(codes(fakeResult({ tris: 4 }), 5), ["glb_triangle_mismatch"]);
    assert.deepEqual(codes(fakeResult({ tris: 4, bbox: [9, 1, 1] })), ["too_large"]);
    const spec = checkMesh({ result: { ...fakeResult(), ok: false, error: { stage: "build", type: "spec_error", message: "lid='dome' not in [...]" } }, glb: null, budget: b });
    assert.equal(spec[0].code, "spec_rejected");
    const guard = checkMesh({ result: { ...fakeResult(), ok: false, error: { stage: "guard", type: "guard_rejected", message: "2 violations" }, guard: [{ line: 3, code: "import_denied", message: "import os" }] }, glb: null, budget: b });
    assert.deepEqual(guard.map((i) => i.code), ["script_rejected", "guard_import_denied"]);
    const lods = checkMesh({ result: fakeResult({ tris: 4 }), glb: parseGlb(tinyGlb({ triangles: 4 })), budget: { ...b, lods: [2000] } });
    assert.ok(lods.some((i) => i.code === "lods_not_built" && i.severity === "warning"));
  });
});

describe("meshgen output manifest", () => {
  it("accepted mesh -> valid manifest, ai-generated-for-user, source ai, library-eligible", () => {
    const r = MeshgenRequestZ.parse(req());
    const m = buildManifest(r, sha256Hex("glb"));
    assert.ok(m.ok);
    assert.equal(m.manifest.legalClass, "ai-generated-for-user"); assert.equal(m.manifest.provenance.source, "ai");
    assert.equal(m.manifest.geometry!.path, "models/crate_a.glb"); assert.match(m.manifest.provenance.note!, /ai-mesh rung=template module=crate@v1/);
    assert.equal(libraryEligible(m.manifest), true);
  });
});

// ---------------------------------------------------------------- worker + queue
type FakeOpts = { status?: BlenderRun["status"]; result?: unknown; glb?: Uint8Array | null; throws?: boolean; onRun?: () => void };
function fakeRunner(o: FakeOpts = {}): BlenderRunner & { calls: number; last: unknown } {
  const r = {
    id: "fake", calls: 0, last: null as unknown,
    async run(job: Parameters<BlenderRunner["run"]>[0]): Promise<BlenderRun> {
      r.calls++; r.last = job; o.onRun?.();
      if (o.throws) throw new Error("ssh exploded");
      const name = String(job.harnessRequest.name);
      const files = new Map<string, Uint8Array>([[`${name}_v0.png`, new Uint8Array([1, 2, 3])], [`${name}_sheet.png`, new Uint8Array([4, 5])]]);
      if (o.glb !== null) files.set(`${name}.glb`, o.glb ?? tinyGlb({ triangles: 4 }));
      return { status: o.status ?? "ok", exitCode: 0, result: o.result ?? fakeResult({ tris: 4, name }), files, logTail: "", wallMs: 1200, lockWaitMs: 5, totalMs: 1300, filesSha256: "f".repeat(64), runner: "fake" };
    },
  };
  return r;
}

describe("meshgen submit + worker", () => {
  it("submit: switched off, invalid spec, scratch off, scan rejects, ok", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    assert.equal((await submitMeshgen(req(), { queue, store, env: {} })).ok, false);
    const bad = await submitMeshgen(req({ spec: { lid: "dome" } } as never), { queue, store, env: ON });
    assert.ok(!bad.ok && bad.code === "invalid" && bad.issues[0].path === "spec.lid");
    const lantern = readFileSync(path.join(FIX, "scratch-lantern.py"), "utf8");
    const s = await submitMeshgen(req({ rung: "scratch", script: lantern, category: "prop" } as never), { queue, store, env: ON });
    assert.ok(!s.ok && s.code === "scratch_off");
    const hostile = await submitMeshgen(req({ rung: "scratch", script: readFileSync(path.join(FIX, "scratch-escape.py"), "utf8") } as never), { queue, store, env: ON3 });
    assert.ok(!hostile.ok && hostile.issues.some((i) => i.code === "scan_import_denied"));
    const good = await submitMeshgen(req(), { queue, store, env: ON });
    assert.ok(good.ok);
    assert.equal(good.job.type, MESHGEN_JOB_TYPE); assert.equal(good.job.workerClass, "linux-cpu"); assert.deepEqual(good.job.inputs, [good.requestKey]);
    assert.ok(await store.has(good.requestKey));
    assert.deepEqual(harnessRequestFor(good.request).budget, { maxTriangles: 8000, decimate: true });
  });
  it("claim types filter: a meshgen worker never takes another linux-cpu job", async () => {
    const queue = createMemoryJobQueue();
    const other = await queue.enqueue({ type: "pack-zip", workerClass: "linux-cpu", projectId: "p", inputs: [], timeoutMs: 1000 });
    assert.equal(await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }), null);
    assert.equal((await queue.claim({ id: "w2", classes: ["linux-cpu"] }))!.id, other.id, "no types = original behaviour");
  });
  it("accepted: glb + manifest + record + renders stored; outputs[0] is the record", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore(), runner = fakeRunner();
    const s = await submitMeshgen(req({ usage: { inputTokens: 1400, outputTokens: 900, cachedInputTokens: 350, round: 1 }, estimate: { totalTokens: 5700, dollars: null } } as never), { queue, store, env: ON });
    assert.ok(s.ok);
    const res = await runMeshgenWorker({ queue, store, runner, workerId: "w1", env: ON }, { maxJobs: 1 });
    assert.deepEqual({ p: res.processed, a: res.accepted }, { p: 1, a: 1 });
    const job = (await queue.get(s.job.id))!;
    assert.equal(job.status, "done");
    const rec: MeshgenRecord = JSON.parse(new TextDecoder().decode((await store.get(job.outputs[0]))!));
    assert.equal(rec.verdict, "accepted"); assert.equal(rec.rung, "template"); assert.equal(rec.module, "crate");
    assert.equal(rec.tokens.usage!.outputTokens, 900); assert.equal(rec.tokens.estimate!.totalTokens, 5700);
    assert.ok(rec.outputs.glb && rec.outputs.manifest && rec.outputs.sheet && rec.outputs.renders.length === 1);
    const man = JSON.parse(new TextDecoder().decode((await store.get(rec.outputs.manifest!))!));
    assert.equal(man.geometry.sha256, rec.outputs.glb!.slice(7), "manifest points at the stored glb bytes");
    assert.deepEqual(job.outputs, [job.outputs[0], rec.outputs.glb, rec.outputs.manifest, rec.outputs.sheet, ...rec.outputs.renders]);
  });
  it("rejected (non-manifold): no glb, no manifest, renders kept for the next round", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    const s = await submitMeshgen(req(), { queue, store, env: ON }); assert.ok(s.ok);
    const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
    const o = await processMeshgenJob(job, { queue, store, runner: fakeRunner({ result: fakeResult({ tris: 4, nonmanifold: 2, name: "crate_a" }) }), workerId: "w", env: ON });
    assert.equal(o.record!.verdict, "rejected"); assert.equal(o.record!.outputs.glb, null); assert.equal(o.record!.outputs.manifest, null);
    assert.ok(o.record!.outputs.sheet); assert.equal((await queue.get(job.id))!.status, "done");
    assert.ok(!(await store.has(`sha256/${sha256Hex(tinyGlb({ triangles: 4 }))}`)), "the rejected glb never entered the store");
  });
  it("busy / transport / runner throw -> not_run and the job fails; timeout -> rejected", async () => {
    for (const [o, verdict, status] of [[{ status: "busy" }, "not_run", "failed"], [{ throws: true }, "not_run", "failed"], [{ status: "timeout" }, "rejected", "done"], [{ status: "crashed" }, "rejected", "done"]] as const) {
      const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
      const s = await submitMeshgen(req(), { queue, store, env: ON }); assert.ok(s.ok);
      const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
      const out = await processMeshgenJob(job, { queue, store, runner: fakeRunner(o as FakeOpts), workerId: "w", env: ON });
      assert.equal(out.record!.verdict, verdict, JSON.stringify(o)); assert.equal((await queue.get(job.id))!.status, status);
    }
  });
  it("a job the sweep expired while Blender ran is not completed (the record stays)", async () => {
    let t = 0;
    const queue = createMemoryJobQueue(() => t), store = createMemoryObjectStore();
    const s = await submitMeshgen(req(), { queue, store, env: ON, timeoutMs: 60_000 }); assert.ok(s.ok);
    const job = (await queue.claim({ id: "w", classes: ["linux-cpu"], types: [MESHGEN_JOB_TYPE] }))!;
    const runner = fakeRunner({ onRun: () => { t = 61_000; void queue.sweep(); } });
    const out = await processMeshgenJob(job, { queue, store, runner, workerId: "w", env: ON, now: () => t });
    assert.equal(out.completed, false); assert.equal((await queue.get(job.id))!.status, "expired"); assert.equal(out.record!.verdict, "accepted");
  });
  it("loop: switched off returns at once; idles out; scratch job refused when the scratch flag is off at run time", async () => {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    assert.equal((await runMeshgenWorker({ queue, store, runner: fakeRunner(), workerId: "w", env: {} })).skipped, "switched off");
    const r = await runMeshgenWorker({ queue, store, runner: fakeRunner(), workerId: "w", env: ON }, { idleMs: 0 });
    assert.equal(r.processed, 0);
    const lantern = readFileSync(path.join(FIX, "scratch-lantern.py"), "utf8");
    const s = await submitMeshgen(req({ rung: "scratch", script: lantern, category: "prop" } as never), { queue, store, env: ON3 }); assert.ok(s.ok);
    const runner = fakeRunner();
    await runMeshgenWorker({ queue, store, runner, workerId: "w", env: ON }, { maxJobs: 1 });
    assert.equal(runner.calls, 0); assert.equal((await queue.get(s.job.id))!.status, "failed");
  });
});

// ---------------------------------------------------------------- node-2 runner (fake transport)
function fakeRemote(reply: (cmd: string, input?: Buffer) => { code: number; stdout: string; stderr?: string }): Remote & { cmds: string[] } {
  const cmds: string[] = [];
  return { cmds, exec: async (c, o) => { cmds.push(c); const r = reply(c, o?.input); return { code: r.code, stdout: r.stdout, stderr: r.stderr ?? "" }; } };
}
const outTar = (files: Record<string, string | Uint8Array>) => tarball(Object.entries(files).map(([name, d]) => ({ name, data: Buffer.from(d as never) }))).toString("base64");

describe("meshgen node-2 runner", () => {
  it("ships harness + request in one tar, runs the sandbox script, reads regular files back", async () => {
    let shipped: Map<string, Uint8Array> | null = null;
    const remote = fakeRemote((_c, input) => {
      shipped = untar(input!);
      return { code: 0, stdout: outTar({ "meta/exit": "0\n", "meta/wall_ms": "11000", "meta/lock_wait_ms": "3", "meta/log.txt": "Blender 5.2.2", "work/result.json": JSON.stringify(fakeResult({ name: "x" })), "work/x.glb": tinyGlb() }) };
    });
    const runner = createNode2BlenderRunner({ remote });
    const r = await runner.run({ jobId: "job_7", harnessRequest: { v: 1, name: "x" }, timeoutMs: 300_000 });
    assert.equal(r.status, "ok"); assert.equal(r.wallMs, 11000); assert.ok(r.files.has("x.glb"));
    assert.equal(r.filesSha256, harnessFiles().sha256);
    const names = [...shipped!.keys()].sort();
    assert.ok(names.includes("in/mg_harness.py") && names.includes("in/sbx-meshgen.sh") && names.includes("in/request.json"));
    assert.match(remote.cmds[0], /sbx-meshgen\.sh" "\$J" '\/tank\/nxeon-build\/tmp\/blender-poc\/blender-5\.2\.2-linux-x64' \d+ \d+/);
    assert.match(remote.cmds[0], /\/tank\/nxeon-build\/tmp\/meshgen\/jobs\/mg-job-7-[0-9a-f]{8}/);
  });
  it("maps lock busy, timeout, missing result and transport failures", async () => {
    const run = (stdout: string, code = 0) => createNode2BlenderRunner({ remote: fakeRemote(() => ({ code, stdout, stderr: "boom" })) }).run({ jobId: "j", harnessRequest: {}, timeoutMs: 120_000 });
    assert.equal((await run(outTar({ "meta/exit": "75" }))).status, "busy");
    assert.equal((await run(outTar({ "meta/exit": "124" }))).status, "timeout");
    assert.equal((await run(outTar({ "meta/exit": "137", "meta/log.txt": "Killed" }))).status, "crashed");
    assert.equal((await run("", 0)).status, "transport");
    assert.equal((await run("", 255)).status, "transport");
    assert.equal((await run("not base64 tar!!")).status, "transport");
  });
  it("untar refuses unsafe names and ignores non-regular entries", () => {
    const t = tarball([{ name: "work/a.txt", data: Buffer.from("a") }]);
    assert.equal(Buffer.from(untar(t).get("work/a.txt")!).toString(), "a");
    const link = Buffer.from(t); link[156] = "2".charCodeAt(0); // symlink type flag (checksum ignored by the reader)
    assert.equal(untar(link).size, 0);
  });
});

describe("meshgen model-facing contract", () => {
  it("one strict tool per rung; template tool carries that template's schema", () => {
    const t = meshToolFor("template", "sword");
    assert.equal(t.name, "mesh_template");
    const props = (t.input_schema as { properties: Record<string, { properties?: Record<string, unknown> }> }).properties;
    assert.ok(props.spec.properties!.blade && props.template);
    assert.equal(meshToolFor("kit").name, "mesh_kit"); assert.equal(meshToolFor("scratch").name, "mesh_script");
    assert.throws(() => meshToolFor("template", "nope"));
    assert.match(meshgenSystemPrompt("template", "crate"), /lid:flat\|inset\|ribbed\|none/);
  });
  it("tool result: errors first, rounds left, next action", () => {
    const rec = { rung: "template", verdict: "rejected", issues: [{ code: "not_unioned", severity: "info", path: "mesh", message: "" }, { code: "non_manifold", severity: "error", path: "objects.lid", message: "" }], stats: fakeResult({ tris: 900 }).stats, decimated: null, outputs: { glb: null, manifest: null, sheet: "sha256/x", renders: [] } } as unknown as MeshgenRecord;
    const r = toolResultFor(rec, 1, 8000);
    assert.equal(r.issues[0].code, "non_manifold"); assert.equal(r.roundsLeft, 2); assert.equal(r.next, "revise"); assert.equal(r.stats!.budget, 8000);
    assert.equal(toolResultFor(rec, 3, 8000).next, "stop");
    assert.equal(toolResultFor({ ...rec, verdict: "not_run" }, 1, 8000).next, "retry_later");
  });
});

