// Cyrus meshgen REAL Blender suite: runs the Python templates/kit/guard inside the node-2 sandbox (build lock, systemd
// unit, no network, user nobody). Skipped unless CYRUS_MESHGEN_REAL=1 and this is node-2 (it shells out locally).
// Run on node-2 WITHOUT devhost's --lock (each Blender run takes the build lock itself):
//   devhost run -- env CYRUS_MESHGEN_REAL=1 npx tsx --test test/cyrus-meshgen-blender.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { hostname } from "node:os";
import { readFileSync } from "node:fs";
import path from "node:path";
import { createMemoryJobQueue, createMemoryObjectStore } from "../lib/cyrus/jobs/asset-jobs";
import { DRAFT_MESH_PROFILE, resolveBudget, type MeshgenRecord, type MeshCategory } from "../lib/cyrus/meshgen";
import { createNode2BlenderRunner } from "../lib/cyrus/meshgen/runner";
import { MESHGEN_JOB_TYPE, processMeshgenJob, submitMeshgen } from "../lib/cyrus/meshgen/worker";

