// Real end-to-end meshgen flights ON node-2: route -> estimate -> submit -> worker loop (in-memory queue + store) ->
// sandboxed Blender -> checks -> manifest. Specs/scripts are hand-written fixtures (no model is called). Writes a JSON
// report, every glb and contact sheet into OUT, and runs the Khronos glTF validator installed for the PoC on each glb.
//   devhost run -- npx tsx scripts/cyrus/meshgen-flights.ts .meshgen-flights      (NOT --lock: each run takes the lock)
//   devhost pull .meshgen-flights/ /root/agent-notes/cyrus-research/blender-poc/meshgen/
// The CYRUS_MESHGEN flags are set only inside this process's env object; nothing global is flipped.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync, existsSync } from "node:fs";
import { hostname } from "node:os";
import path from "node:path";
import { createMemoryJobQueue, createMemoryObjectStore } from "../../lib/cyrus/jobs/asset-jobs";
import { DRAFT_MESH_PROFILE, resolveBudget, routeMesh, estimateCost, type MeshCategory, type MeshgenRecord, type Rung } from "../../lib/cyrus/meshgen";
import { createNode2BlenderRunner, NODE2_BLENDER_DIR, type BlenderRun } from "../../lib/cyrus/meshgen/runner";
import { MESHGEN_JOB_TYPE, runMeshgenWorker, submitMeshgen } from "../../lib/cyrus/meshgen/worker";

type Flight = { id: string; prompt: string; category: MeshCategory; rung: Rung; template?: string; spec?: unknown; scriptFile?: string; maxTriangles?: number; bypassSubmitScan?: boolean; expect?: string };
const ROOT = path.resolve(__dirname, "..", "..");
const FIX = path.join(ROOT, "test", "fixtures", "cyrus-meshgen");
const OUT = path.resolve(process.argv[2] ?? ".meshgen-flights");
const ENV = { CYRUS_MESHGEN: "1", CYRUS_MESHGEN_SCRATCH: "1" };
const VALIDATOR = "/tank/nxeon-build/tmp/blender-poc/val/v.js";
const NODE = "/opt/nxeon-build/node/bin/node";

async function main() {
  if (hostname() !== "nxeon-fsn1") throw new Error("run this on node-2 via devhost run");
  mkdirSync(OUT, { recursive: true });
  // Blender identity: the PoC's tarball, checked against the published sha256 file it was downloaded with
  const tarPath = path.join(path.dirname(NODE2_BLENDER_DIR), "blender-5.2.2-linux-x64.tar.xz");
  const tarSha = createHash("sha256").update(readFileSync(tarPath)).digest("hex");
  const published = readFileSync(path.join(path.dirname(NODE2_BLENDER_DIR), "blender-5.2.2.sha256"), "utf8");
  const blender = { dir: NODE2_BLENDER_DIR, tarballSha256: tarSha, matchesPublished: published.includes(tarSha) };

  const flights: Flight[] = JSON.parse(readFileSync(path.join(FIX, "flights.json"), "utf8")).flights;
  const runner = createNode2BlenderRunner({ transport: "local" });
  const rows: unknown[] = [];

  // 1. the variant self-test (no render)
  const st = await runner.run({ jobId: "selftest", harnessRequest: { v: 1, name: "selftest", rung: "selftest" }, timeoutMs: 10 * 60_000 });
  const selftest = { status: st.status, wallMs: st.wallMs, lockWaitMs: st.lockWaitMs, result: (st.result as { selftest?: unknown; ok?: boolean } | null) };

  // 2. one queue + store for all flights, one worker, jobs processed in order
  for (const f of flights) {
    const queue = createMemoryJobQueue(), store = createMemoryObjectStore();
    const route = await routeMesh({ prompt: f.prompt, game: DRAFT_MESH_PROFILE.game, category: f.category, availability: { scratch: true }, forceRung: f.rung === "scratch" ? "scratch" : undefined });
    const b = resolveBudget(DRAFT_MESH_PROFILE, f.category);
    if (!b.ok) throw new Error(b.reason);
    const budget = f.maxTriangles ? { ...b.budget, maxTriangles: f.maxTriangles } : b.budget;
    const est = estimateCost(f.rung);
    const base = { v: 1, assetId: f.id, projectId: "flights", game: DRAFT_MESH_PROFILE.game, category: f.category, prompt: f.prompt, budget, render: { samples: 32 }, estimate: { totalTokens: est.expected.totalTokens, dollars: est.dollars } };
    const body = f.rung === "scratch" ? { rung: "scratch", script: readFileSync(path.join(FIX, f.scriptFile!), "utf8") } : f.rung === "kit" ? { rung: "kit", kit: "hardsurface", spec: f.spec } : { rung: "template", template: f.template, spec: f.spec };
    let submitted: unknown;
    if (f.bypassSubmitScan) {
      const key = await store.put(new TextEncoder().encode(JSON.stringify({ ...base, ...body })));
      submitted = { bypassed: true, job: (await queue.enqueue({ type: MESHGEN_JOB_TYPE, workerClass: "linux-cpu", projectId: "flights", inputs: [key], timeoutMs: 12 * 60_000 })).id };
    } else {
      const s = await submitMeshgen({ ...base, ...body } as never, { queue, store, env: ENV });
      submitted = s.ok ? { job: s.job.id } : { refused: s.code, issues: s.issues };
    }
    let rec: MeshgenRecord | null = null, run: BlenderRun | null = null;
    const t0 = Date.now();
    await runMeshgenWorker({ queue, store, runner, workerId: "flights@node-2", env: ENV, onRecord: (r, x) => { rec = r; run = x; } }, { maxJobs: 1 });
    const endToEndMs = Date.now() - t0;
    const r = rec as MeshgenRecord | null, x = run as BlenderRun | null;
    let validator: string | null = null;
    if (r?.outputs.glb) {
      const glb = (await store.get(r.outputs.glb))!;
      const file = path.join(OUT, `${f.id}.glb`); writeFileSync(file, glb);
      if (existsSync(VALIDATOR)) {
        try { validator = execFileSync(NODE, [VALIDATOR, file], { cwd: path.dirname(VALIDATOR), timeout: 60_000 }).toString().trim().replace(file, path.basename(file)); }
        catch (e) { validator = `validator failed: ${(e as Error).message.slice(0, 200)}`; }
      }
    }
    if (r?.outputs.sheet) writeFileSync(path.join(OUT, `${f.id}-sheet.png`), (await store.get(r.outputs.sheet))!);
    rows.push({
      id: f.id, prompt: f.prompt, rung: f.rung, expect: f.expect ?? "accepted",
      route: route.ok ? { rung: route.rung, templateId: route.templateId, reason: route.reason, warnings: route.warnings } : { refused: route.code, reason: route.reason },
      estimate: { expectedTokens: est.expected.totalTokens, worstCaseTokens: est.worstCase.totalTokens, basis: est.basis, dollars: est.dollars },
      submitted, verdict: r?.verdict ?? null, notRunReason: r?.notRunReason,
      issues: r?.issues ?? [], stats: r?.stats ? { objects: r.stats.objects, tris: r.stats.tris, materials: r.stats.materials, shells: r.stats.shells, nonmanifold: r.stats.nonmanifold_edges, bbox_m: r.stats.bbox_m, perObject: r.stats.per_obj.map((o) => [o.name, o.tris, o.nonmanifold_edges, o.shells]) } : null,
      decimated: r?.decimated ?? null,
      timings: x ? { endToEndMs, lockWaitMs: x.lockWaitMs, sandboxWallMs: x.wallMs, blenderSeconds: r?.compute.blenderSeconds, harness: (x.result as { timings?: unknown } | null)?.timings ?? null } : { endToEndMs },
      glbBytes: (x?.result as { glb?: { bytes?: number } } | null)?.glb?.bytes ?? null, gltfValidator: validator,
      engine: r?.engine ?? null,
    });
    console.log(`${f.id}: ${r?.verdict ?? "no record"} ${r?.stats?.tris ?? "-"} tris, sandbox ${x?.wallMs ?? "-"} ms, end-to-end ${endToEndMs} ms`);
  }
  const report = { date: new Date().toISOString(), host: hostname(), blender, runner: runner.id, selftest, flights: rows,
    honesty: "Specs and scripts are hand-written fixtures standing in for model replies; no model was called, so token numbers are estimates, not usage. Quality judgements are not part of this file." };
  writeFileSync(path.join(OUT, "meshgen-flights.json"), JSON.stringify(report, null, 2));
  console.log(`wrote ${path.join(OUT, "meshgen-flights.json")}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

