      issues: r?.issues ?? [], stats: r?.stats ? { objects: r.stats.objects, tris: r.stats.tris, materials: r.stats.materials, shells: r.stats.shells, nonmanifold: r.stats.nonmanifold_edges, bbox_m: r.stats.bbox_m, perObject: r.stats.per_obj.map((o) => [o.name, o.tris, o.nonmanifold_edges, o.shells]) } : null,
      decimated: r?.decimated ?? null,
      timings: x ? { endToEndMs, lockWaitMs: x.lockWaitMs, sandboxWallMs: x.wallMs, blenderSeconds: r?.compute.blenderSeconds, harness: (x.result as { timings?: unknown } | null)?.timings ?? null } : { endToEndMs },
      glbBytes: (x?.result as { glb?: { bytes?: number } } | null)?.glb?.bytes ?? null, gltfValidator: validator,
      engine: r?.engine ?? null,
    });
    console.log(`${f.id}: ${r?.verdict ?? "no record"} ${r?.stats?.tris ?? "-"} tris, sandbox ${x?.wallMs ?? "-"} ms, end-to-end ${endToEndMs} ms`);
  }
  const report = { date: new Date().toISOString(), host: hostname(), blender, runner: runner.id, selftest, flights: rows,
    honesty: "Specs and scripts are hand-written fixtures standing in for model replies; no model was called, so token numbers are estimates, not usage. Quality judgements are not part of this file." };
  writeFileSync(path.join(OUT, "meshgen-flights.json"), JSON.stringify(report, null, 2));
  console.log(`wrote ${path.join(OUT, "meshgen-flights.json")}`);
}

main().catch((e) => { console.error(e); process.exit(1); });

